function focusableIn(root){return [...root.querySelectorAll('button:not([disabled]),a[href],input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])')].filter(x=>!x.closest('.hidden')&&x.getClientRects().length)}
function trapDialogFocus(event,root){const items=focusableIn(root);if(!items.length){event.preventDefault();root.focus?.();return}const first=items[0],last=items[items.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}
function topDialog(){if(!$('#global-search')?.classList.contains('hidden'))return $('#global-search');if(!$('#modal')?.classList.contains('hidden'))return $('#modal');if(!$('#mobile-nav-layer')?.classList.contains('hidden'))return $('#mobile-nav-layer');return null}
function syncOverlayState(){const locked=!$('#modal')?.classList.contains('hidden')||!$('#global-search')?.classList.contains('hidden');$('#main-content')?.toggleAttribute('inert',locked);$('.sidebar')?.toggleAttribute('inert',locked);document.body.classList.toggle('overlay-open',locked)}
function clearModalFieldError(control){if(!control)return;const field=control.closest('.field');control.removeAttribute('aria-invalid');const errorId=control.getAttribute('aria-errormessage');if(errorId)field?.querySelector(`#${CSS.escape(errorId)}`)?.remove();control.removeAttribute('aria-errormessage')}
function modalErrorField(error,form){const detail=Array.isArray(error?.details)?error.details[0]:null,name=error?.fieldName||detail?.loc?.[detail.loc.length-1];return name?form.elements?.[name]||form.querySelector(`[name="${CSS.escape(String(name))}"]`):null}
function showModalFormError(error,form){form.querySelectorAll('[aria-invalid="true"]').forEach(clearModalFieldError);const banner=form.querySelector('#modal-form-error'),control=modalErrorField(error,form),message=error?.message||'提交失败，请检查填写内容';if(control){const field=control.closest('.field'),errorId=`${control.id||formFieldId(control.name)}-error`,note=document.createElement('small');note.id=errorId;note.className='field-error';note.textContent=message;field?.appendChild(note);control.setAttribute('aria-invalid','true');control.setAttribute('aria-errormessage',errorId);control.focus();banner?.classList.add('hidden');return}if(banner){banner.textContent=message;banner.classList.remove('hidden');banner.focus()}else toast(message,true)}
function openModal(title,body,onSubmit,options={}){modalReturnFocus=document.activeElement;clearTimeout(modalCloseTimer);const modal=$('#modal');modal.classList.remove('is-closing');$('#modal-title').textContent=title;$('#modal-body').innerHTML=`<div id="modal-form-error" class="form-error hidden" role="alert" tabindex="-1"></div><div class="modal-form-grid">${body}</div>`;const card=$('#modal .modal-card'),form=$('#modal-form'),submit=$('#modal-form button[type=submit]'),actions=$('#modal-form .modal-actions');card.className=`modal-card${options.variant?` ${options.variant}`:''}`;actions.style.display=options.readOnly?'none':'';submit.disabled=false;submit.textContent=options.submitLabel||'保存';modal.classList.remove('hidden');syncOverlayState();requestAnimationFrame(()=>(form.querySelector('input, select, textarea, button')||card)?.focus());form.oninput=e=>{clearModalFieldError(e.target);form.querySelector('#modal-form-error')?.classList.add('hidden')};form.onchange=form.oninput;form.onsubmit=async e=>{e.preventDefault();const original=submit.textContent;submit.disabled=true;submit.textContent=options.busyLabel||'正在保存…';try{const result=await onSubmit(new FormData(e.target));closeModal();if(!result?.silent)toast('保存成功');if(result?.afterClose)result.afterClose();else loadCurrent()}catch(err){submit.disabled=false;submit.textContent=original;showModalFormError(err,e.target)}}}
function closeModal({immediate=false}={}){const modal=$('#modal');if(!modal||modal.classList.contains('hidden'))return;clearTimeout(modalCloseTimer);const finish=()=>{modal.classList.add('hidden');modal.classList.remove('is-closing');const card=$('#modal .modal-card'),submit=$('#modal-form button[type=submit]'),actions=$('#modal-form .modal-actions');card.className='modal-card';actions.style.display='';submit.disabled=false;submit.textContent='保存';syncOverlayState();if(modalReturnFocus?.isConnected)modalReturnFocus.focus();modalReturnFocus=null};if(immediate||matchMedia('(prefers-reduced-motion: reduce)').matches){finish();return}modal.classList.add('is-closing');modalCloseTimer=setTimeout(finish,160)}
function closeAccountMenu(){const panel=$('#account-menu-panel'),trigger=$('#account-menu-trigger');panel?.classList.add('hidden');trigger?.setAttribute('aria-expanded','false')}
function toggleAccountMenu(){const panel=$('#account-menu-panel'),trigger=$('#account-menu-trigger');if(!panel||!trigger)return;const opening=panel.classList.contains('hidden');panel.classList.toggle('hidden',!opening);trigger.setAttribute('aria-expanded',String(opening));if(opening)requestAnimationFrame(()=>panel.querySelector('button,a')?.focus())}
function isEditableTarget(target){return Boolean(target?.closest?.('input,textarea,[contenteditable="true"]'))}
async function deleteAdminResource(resourceType,id,label,endpoint){if(currentUser?.role!=='admin')return toast('只有管理员可以删除记录',true);if(!confirm(`将“${label}”移入回收站？关联的财务、库存、附件和操作历史会保留，可随时撤销。`))return;const deletion=await api(endpoint,{method:'DELETE'});appUndoStack.push({resourceType,id,label,endpoint,deletionId:deletion.id});appRedoStack=[];toast(`已移入回收站 · Ctrl/Command+Z 可撤销`);await warm();loadCurrent()}
async function undoAppAction(){if(appHistoryBusy)return;const action=appUndoStack.pop();if(!action)return toast('没有可撤销的系统操作');appHistoryBusy=true;try{await api(`/api/trash/${action.deletionId}/restore`,{method:'POST'});appRedoStack.push(action);toast(`已撤销删除：${action.label}`);await warm();loadCurrent()}catch(error){appUndoStack.push(action);toast(error.message,true)}finally{appHistoryBusy=false}}
async function redoAppAction(){if(appHistoryBusy)return;const action=appRedoStack.pop();if(!action)return toast('没有可重做的系统操作');appHistoryBusy=true;try{const deletion=await api(action.endpoint,{method:'DELETE'});action.deletionId=deletion.id;appUndoStack.push(action);toast(`已重新删除：${action.label}`);await warm();loadCurrent()}catch(error){appRedoStack.push(action);toast(error.message,true)}finally{appHistoryBusy=false}}
async function restoreTrashRecord(id,label){try{await api(`/api/trash/${id}/restore`,{method:'POST'});toast(`已恢复：${label}`);await warm();loadCurrent()}catch(error){toast(error.message,true)}}
let globalSearchTimer=null,globalSearchResults=[],globalSearchIndex=0;
function openGlobalSearch(){if(!currentUser)return;globalSearchReturnFocus=document.activeElement;$('#global-search').classList.remove('hidden');syncOverlayState();const input=$('#global-search-input');requestAnimationFrame(()=>{input.focus();input.select()});if(input.value.trim())runGlobalSearch(input.value)}
function closeGlobalSearch(){$('#global-search').classList.add('hidden');syncOverlayState();if(globalSearchReturnFocus?.isConnected)globalSearchReturnFocus.focus();globalSearchReturnFocus=null}
function renderGlobalSearch(){const root=$('#global-search-results');if(!globalSearchResults.length){root.innerHTML='<div class="empty">没有找到匹配记录</div>';return}root.innerHTML=globalSearchResults.map((x,i)=>`<button type="button" class="search-result ${i===globalSearchIndex?'active':''}" data-index="${i}" onclick="openRecord('${x.kind}',${x.id})"><small>${esc(x.category)}</small><strong>${esc(x.number)}<br><small>${esc(x.title||'')}</small></strong><em>打开 ↵</em></button>`).join('');root.querySelector('.active')?.scrollIntoView({block:'nearest'})}
async function runGlobalSearch(value){const q=value.trim();if(!q){globalSearchResults=[];$('#global-search-results').innerHTML='<div class="empty">输入关键词开始检索</div>';return}try{globalSearchResults=await api(`/api/search?q=${encodeURIComponent(q)}`);globalSearchIndex=0;renderGlobalSearch()}catch(error){$('#global-search-results').innerHTML=`<div class="alert">检索失败：${esc(error.message)}</div>`}}
function bindGlobalSearch(){const input=$('#global-search-input');input.addEventListener('input',e=>{clearTimeout(globalSearchTimer);globalSearchTimer=setTimeout(()=>runGlobalSearch(e.target.value),180)});input.addEventListener('keydown',e=>{if(e.key==='ArrowDown'){e.preventDefault();globalSearchIndex=Math.min(globalSearchIndex+1,globalSearchResults.length-1);renderGlobalSearch()}else if(e.key==='ArrowUp'){e.preventDefault();globalSearchIndex=Math.max(globalSearchIndex-1,0);renderGlobalSearch()}else if(e.key==='Enter'&&globalSearchResults[globalSearchIndex]){e.preventDefault();const x=globalSearchResults[globalSearchIndex];openRecord(x.kind,x.id)}});$('#global-search').addEventListener('click',e=>{if(e.target.id==='global-search')closeGlobalSearch()})}
async function warm(){[cache.customers,cache.devices,cache.orders,cache.inventory]=await Promise.all([api('/api/customers'),api('/api/devices'),api('/api/orders'),api('/api/inventory/items')])}
async function loadCurrent({focus=false}={}){pageLoadController?.abort();const controller=new AbortController(),generation=++pageLoadGeneration,page=current;pageLoadController=controller;const title=pages.find(x=>x[0]===page)?.[1]||'管理中心',group=pageGroup(page),content=$('#content');$('#page-title').textContent=title;if($('#page-context'))$('#page-context').textContent=`${group.label} · ${group.hint}`;content.classList.remove('is-ready');content.setAttribute('aria-busy','true');content.innerHTML='<div class="loading"><span aria-hidden="true"></span><strong>正在载入</strong><small>准备当前工作区…</small></div>';try{await render[page]();if(generation!==pageLoadGeneration||controller.signal.aborted)return;if(focus)content.focus({preventScroll:true})}catch(e){if(e?.name==='AbortError'||generation!==pageLoadGeneration)return;content.innerHTML=`<div class="alert">载入失败：${esc(e.message)}</div>`;if(focus)content.focus({preventScroll:true})}finally{if(generation!==pageLoadGeneration)return;content.removeAttribute('aria-busy');pageLoadController=null;requestAnimationFrame(()=>content.classList.add('is-ready'))}}
