async function newCalibration(){await warm();if(!cache.orders.length){toast('请先创建维修工单',true);return}openModal('按官方流程记录标定',selectField('repair_order_id','工单',cache.orders.map(x=>[x.id,x.order_no]))+selectField('device_id','设备',cache.devices.map(x=>[x.id,`${x.serial_number} · ${x.model}`]))+field('calibration_type','标定类型','text','value="DJI 云台自动标定"')+field('tool_name','官方工具名称','text','placeholder="例如 DJI Fly"')+field('tool_version','工具/应用版本')+selectField('status','结果',[['completed','完成'],['failed','失败'],['recorded','仅记录']])+field('remarks','复测结果与备注','textarea','full')+'<div id="calibration-guide" class="field full"><div class="loading">正在读取该设备的官方流程…</div></div>',async f=>{const o=Object.fromEntries(f);o.repair_order_id=+o.repair_order_id;o.device_id=+o.device_id;return api('/api/calibrations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)})});const form=$('#modal-form'),orderSelect=form.elements.repair_order_id,deviceSelect=form.elements.device_id;const syncDevice=()=>{const order=cache.orders.find(x=>x.id===Number(orderSelect.value));if(order)deviceSelect.value=String(order.device_id);loadCalibrationGuide(Number(deviceSelect.value))};orderSelect.addEventListener('change',syncDevice);deviceSelect.addEventListener('change',()=>loadCalibrationGuide(Number(deviceSelect.value)));syncDevice()}
async function loadCalibrationGuide(deviceId){const root=$('#calibration-guide');if(!root||!deviceId)return;try{const c=await api(`/api/calibration/capabilities?device_id=${deviceId}`);root.innerHTML=`<div class="alert"><strong>${esc(c.brand)} ${esc(c.model)}</strong><br>建议工具：${esc(c.recommended_tool)}<br><br><strong>标定前：</strong>${c.preconditions.map(esc).join('；')}。<br><br><strong>流程：</strong>${c.workflow.map((x,i)=>`${i+1}. ${esc(x)}`).join('<br>')}<br><br><small>当前桌面系统直接标定：不支持；Mobile SDK 桥接：尚未连接。</small></div>`}catch(e){root.innerHTML=`<div class="alert">无法读取流程：${esc(e.message)}</div>`}}
