function quickEntryHtml(){return `<form id="quick-form"><div class="quick-layout"><div><div class="panel quick-section"><h2>客户与设备</h2><div class="form-grid"><label>客户姓名<input name="customer_name" required placeholder="必填"></label><label>联系电话<input name="phone" placeholder="可空，用于匹配已有客户资料"></label><label>客户邮箱<input name="email" type="email" placeholder="发送报价邮件时必填"></label><label>微信<input name="wechat"></label><label>公司名称<input name="company_name"></label><label>客户类型<select name="customer_type"><option value="individual">个人</option><option value="company">企业</option></select></label><label class="wide">地址<textarea name="address"></textarea></label><label>品牌<input name="brand" value="DJI" required></label><label>设备型号<input name="model" required placeholder="例如 Mini 4 Pro"></label><label>序列号<input name="serial_number" placeholder="允许重复；留空建立临时设备"></label><label>质保状态<input name="warranty_status"></label></div></div><div class="panel quick-section"><h2>收机与故障</h2><div class="form-grid"><label class="wide">故障描述<textarea name="fault_description" required placeholder="客户反馈和主要故障"></textarea></label><label class="wide">收机状态<textarea name="intake_condition" placeholder="外观、进水、碰撞等"></textarea></label><label class="wide">随件附件<textarea name="intake_accessories" placeholder="电池、遥控器、桨叶等"></textarea></label><label>优先级<select name="priority"><option value="normal">普通</option><option value="high">加急</option><option value="urgent">紧急</option></select></label><label class="wide">给客户的备注<textarea name="customer_notes"></textarea></label></div></div><div class="panel quick-section"><div class="panel-title"><h2>报价项目</h2><button type="button" class="ghost" onclick="addQuickLine()">＋ 添加项目</button></div><div class="quick-line-head"><span>库存物料/自定义</span><span>项目名称</span><span>数量</span><span>售价</span><span>成本</span><span></span></div><div id="quick-lines"></div><div class="form-grid fee-grid"><label>人工费<input name="labor_fee" type="number" step="0.01" value="0"></label><label>运费<input name="shipping_fee" type="number" step="0.01" value="0"></label><label>优惠<input name="discount" type="number" step="0.01" value="0"></label>${paymentUrlField()}</div></div><div class="panel quick-actions"><label><input name="generate_pdf" type="checkbox" checked> 自动生成 PDF 报价单</label><label><input name="send_email" type="checkbox"> 同时发送报价邮件</label><button class="primary" type="submit">保存并完成快捷录入</button></div></div><aside class="quick-preview"><div class="panel sticky"><p class="eyebrow">实时预览</p><h2 id="quick-preview-customer">待填写客户</h2><p id="quick-preview-device" class="muted">待填写设备</p><div class="preview-order"><small>故障描述</small><p id="quick-preview-fault">—</p></div><div id="quick-preview-lines" class="preview-lines"><div class="muted">尚未添加报价项目</div></div><div class="preview-total"><span>报价合计</span><strong id="quick-preview-total">¥ 0.00</strong></div><p class="muted">每次收机会创建独立设备归属记录；同一序列号可保留多次流转历史。</p><div id="quick-result"></div></div></aside></div></form>`}
