async function configureEmail(){const c=await api('/api/email/config');openModal('发件端服务与个性化设置',selectField('mode','发送模式',[['mock','安全模拟（不外发）'],['smtp','SMTP 实际投递']])+field('sender','发信邮箱 (Sender Email)','email',`value="${esc(c.sender||'')}"`)+field('smtp_host','SMTP 服务器 (Host)','text',`value="${esc(c.smtp_host||'smtp.feishu.cn')}"`)+field('smtp_port','端口号（常用 465）','number',`min="1" max="65535" value="${c.smtp_port||465}"`)+field('password',c.password_configured?'授权码（已配置，留空保持不变）':'授权码','password','autocomplete="new-password"')+field('from_name','发件显示名称','text',`value="${esc(c.from_name||'服务中心')}"`)+field('reply_to','回复邮箱（可空）','email',`value="${esc(c.reply_to||'')}"`)+selectField('use_starttls','非 465 端口安全连接',[['true','服务器支持时启用 STARTTLS'],['false','不启用 STARTTLS']])+field('timeout_seconds','连接超时（秒）','number',`min="3" max="120" value="${c.timeout_seconds||12}"`)+selectField('clear_password','授权码操作',[['false','保留当前授权码'],['true','清除已保存授权码']]),async f=>{const o=Object.fromEntries(f);o.smtp_port=Number(o.smtp_port);o.timeout_seconds=Number(o.timeout_seconds);o.use_starttls=o.use_starttls==='true';o.clear_password=o.clear_password==='true';if(!o.password)delete o.password;return api('/api/email/config',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)})});setTimeout(()=>{$('#modal-form [name=mode]').value=c.mode;$('#modal-form [name=use_starttls]').value=String(c.use_starttls)},0)}
const baseCalibrationRenderer=render.calibrations;
render.calibrations=async()=>{
  await baseCalibrationRenderer();
  const [lab,ports,devices]=await Promise.all([api('/api/calibration/lab/profiles'),api('/api/calibration/lab/ports'),api('/api/calibration/lab/devices')]);
  const profileOptions=lab.profiles.map(x=>`<option value="${esc(x.profile_id)}">${esc(x.display_name)}</option>`).join('');
  const portSummary=ports.available
    ? (ports.ports.length?`发现 ${ports.ports.length} 个串口（只读枚举，未打开）`:'未发现串口；未打开任何硬件端口')
    : '串口枚举组件尚未安装；模拟器仍可使用';
  const connectedDevice=devices.devices?.[0];
  const interfaceCounts=connectedDevice?.interfaces?.reduce((acc,item)=>{acc[item.role]=(acc[item.role]||0)+1;return acc}, {})||{};
  const devicePanel=connectedDevice?`<div class="readonly-device"><div><span class="readonly-dot"></span><strong>${esc(connectedDevice.product_name)}</strong><span class="badge green">PnP 只读识别</span></div><p>USB ${esc(connectedDevice.vendor_id)}:${esc(connectedDevice.product_id)} · RNDIS ${interfaceCounts.rndis_network||0} · 存储 ${interfaceCounts.mass_storage||0} · Bulk ${interfaceCounts.vendor_bulk_unopened||0}</p><small>未打开 USB/串口/网络/存储句柄；未发送控制传输或设备指令。Avata 2 不在当前标定档案中。</small></div>`:'<div class="readonly-device empty-device"><strong>未发现已知 DJI USB 设备</strong><small>发现器只读取 Windows PnP 与注册表缓存。</small></div>';
  $('#content').insertAdjacentHTML('afterbegin',`<div class="panel calibration-lab"><div class="panel-title"><div><p class="eyebrow">自研协议实验室 · 第一阶段</p><h2>云台标定模拟器</h2></div><span class="badge amber">仅模拟，不连接真机</span></div>${devicePanel}<p class="muted">独立实现 DUML 数据包编解码、CRC 校验与标定状态机；当前没有真实设备执行入口。</p><div class="lab-controls"><label>研究档案<select id="lab-profile">${profileOptions}</select></label><label>标定项目<select id="lab-kind"><option value="joint_coarse">关节粗标定</option><option value="linear_hall">线性霍尔标定</option></select></label><button class="primary" onclick="runCalibrationSimulation()">运行安全模拟</button></div><div class="lab-port-note">${esc(portSummary)}</div><div id="lab-result" class="lab-result"><span class="muted">选择研究档案后运行；模拟过程只使用内存设备。</span></div></div>`);
};
async function runCalibrationSimulation(){
  const root=$('#lab-result'),profile_id=$('#lab-profile').value,calibration_kind=$('#lab-kind').value;
  root.innerHTML='<div class="loading">正在执行本地协议模拟…</div>';
  try{
    const result=await api('/api/calibration/lab/simulate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({profile_id,calibration_kind})});
    root.innerHTML=`<div class="lab-result-head"><strong>模拟完成</strong><span class="badge green">未执行硬件 I/O</span></div><div class="lab-packets"><div><small>请求数据包</small><code>${esc(result.request_hex)}</code></div><div><small>模拟应答</small><code>${esc(result.response_hex)}</code></div></div><div class="lab-timeline">${result.events.map(x=>`<div><span style="--progress:${x.progress}%"></span><strong>${x.progress}% · ${esc(x.state)}</strong><p>${esc(x.message)}</p></div>`).join('')}</div><p class="muted">耗时 ${esc(result.elapsed_ms)} ms；往返解码校验：${result.request_round_trip_valid?'通过':'失败'}。</p>`;
  }catch(error){root.innerHTML=`<div class="alert">模拟失败：${esc(error.message)}</div>`}
}
