function pointMapOptionValues(key){return [...new Set(pointMapCatalog.map(x=>String(x.map[key]||'未分类')).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'zh-CN'))}
function refreshPointMapFilterOptions(){for(const el of document.querySelectorAll('[data-point-map-key]')){const current=el.value,values=pointMapOptionValues(el.dataset.pointMapKey);el.innerHTML='<option value="">全部</option>'+values.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('');if(values.includes(current))el.value=current}}
