function openPointMapLibrary(){current='point_maps';history.replaceState(null,'','#point_maps');nav();loadCurrent()}
async function newDamageSopTemplate(){
  openModal('新建定损 SOP',field('title','SOP 名称','text','full required')+field('brand','品牌','text','value="通用" required')+field('product_category','产品类别','text','value="数码产品" required')+field('series','产品系列')+field('model_pattern','适用型号','text','value="*" required placeholder="* 表示通用；也可填写型号关键字"')+field('version','版本','text','value="1.0" required')+selectField('access_level','访问级别',[['internal','内部'],['restricted','受限']])+field('description','流程说明','textarea','full')+field('source_reference','来源/编制依据','text','full placeholder="只记录来源，不在公网复制受限原文"'),async f=>{const o=requiredFormValues(f,{title:'SOP 名称',brand:'品牌',product_category:'产品类别',model_pattern:'适用型号',version:'版本'});o.status='draft';o.steps=[];const d=await api('/api/damage-sop/templates',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)});return {silent:true,afterClose:()=>showDamageSopTemplate(d.template.id)}});
}
async function showDamageSopTemplate(id){
  const d=await api(`/api/damage-sop/templates/${id}`),t=d.template,editable=damageKnowledgeEditor()&&t.status==='draft';
  $('#page-title').textContent='SOP 模板';
  const actions=`<button class="ghost" onclick="openDamageSopHome()">← 返回定损中心</button><div>${editable?`<button class="ghost" onclick="addDamageSopStep(${id})">添加步骤</button> <button class="primary" onclick="publishDamageSop(${id})">发布版本</button>`:''}</div>`;
  $('#content').innerHTML=`<div class="toolbar">${actions}</div><div class="panel"><div class="panel-title"><div><p class="eyebrow">${esc(t.brand)} · ${esc(t.product_category)} · ${esc(t.model_pattern)}</p><h2>${esc(t.title)} · V${esc(t.version)}</h2></div>${badge(t.status)}</div><p>${esc(t.description||'暂无说明')}</p><div class="knowledge-meta"><span>系列：${esc(t.series||'-')}</span><span>访问：${esc(t.access_level)}</span><span>来源：${esc(t.source_reference||'未登记')}</span></div></div><div class="sop-step-list">${d.steps.length?d.steps.map((x,i)=>{const map=d.point_maps.find(m=>m.id===x.point_map_id);return `<article class="sop-template-step risk-${esc(x.risk_level)}"><div class="step-index">${i+1}</div><div><small>${esc(x.section||'未分组')} · ${esc(x.step_code)} · ${esc(damageCheckTypeLabels[x.check_type]||x.check_type)}</small><h3>${esc(x.title)}</h3><p>${esc(x.instruction)}</p>${x.expected_result?`<div class="expected"><strong>合格标准</strong>${esc(x.expected_result)}</div>`:''}${x.fail_conclusion?`<div class="failure"><strong>异常结论</strong>${esc(x.fail_conclusion)}</div>`:''}${map?`<button class="ghost tiny" onclick="showPointMap(${map.id})">查看点位图：${esc(map.title)}</button>`:''}</div><span>${x.required?'<span class="badge amber">必做</span>':'<span class="badge gray">选做</span>'}</span></article>`}).join(''):'<div class="empty">暂无步骤。先添加检查步骤，再发布模板。</div>'}</div>`;
}
async function addDamageSopStep(templateId){
  const maps=await api('/api/point-maps?status=published');
  openModal('添加 SOP 步骤',field('step_code','步骤编号','text','required placeholder="例如 PWR-010"')+field('sort_order','顺序','number','min="0" value="10"')+field('section','章节','text','placeholder="例如 外观、供电、功能"')+field('title','步骤名称','text','full required')+field('instruction','操作方法','textarea','full required')+selectField('check_type','检查类型',Object.entries(damageCheckTypeLabels))+selectField('risk_level','风险等级',[['normal','普通'],['caution','注意'],['danger','危险']])+selectField('required','是否必做',[['true','必做'],['false','选做']])+field('module_name','关联模块')+field('expected_result','合格标准','textarea','full')+field('fail_conclusion','异常时建议结论','textarea','full')+selectField('point_map_id','关联点位图',[['','不关联'],...maps.map(x=>[x.map.id,x.map.title])])+selectField('point_marker_id','关联点位',[['','先选择点位图']]),async f=>{const o=requiredFormValues(f,{step_code:'步骤编号',title:'步骤名称',instruction:'操作方法'});o.sort_order=Number(o.sort_order||0);o.required=o.required==='true';for(const key of ['point_map_id','point_marker_id']){if(o[key])o[key]=Number(o[key]);else delete o[key]}for(const key of ['section','module_name','expected_result','fail_conclusion'])if(!o[key])delete o[key];const d=await api(`/api/damage-sop/templates/${templateId}/steps`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)});return {...d,silent:true,afterClose:()=>showDamageSopTemplate(templateId)}});
  const form=$('#modal-form'),mapSelect=form.elements.point_map_id,markerSelect=form.elements.point_marker_id;
  mapSelect.addEventListener('change',async()=>{markerSelect.innerHTML='<option value="">不指定具体点位</option>';if(!mapSelect.value)return;const detail=await api(`/api/point-maps/${mapSelect.value}`);markerSelect.innerHTML+=[...detail.markers].map(x=>`<option value="${x.id}">${esc(x.marker_code)} · ${esc(x.label)}</option>`).join('')});
}
async function publishDamageSop(id){if(!confirm('发布后此版本将冻结，修改内容需要创建新版本。确认发布？'))return;await api(`/api/damage-sop/templates/${id}/publish`,{method:'POST'});toast('SOP 已发布');showDamageSopTemplate(id)}
async function newPointMap(){
  openModal('新建点位图',field('title','点位图名称','text','full required')+field('brand','品牌','text','value="通用" required')+field('product_category','产品类别','text','value="数码产品" required')+field('series','产品系列')+field('model_pattern','适用型号','text','value="*" required')+field('module_name','模块/板件','text','required')+field('board_code','板件代号')+field('version','版本','text','value="1.0" required')+selectField('access_level','访问级别',[['internal','内部'],['restricted','受限']])+field('source_reference','来源/编制依据','text','full'),async f=>{const o=requiredFormValues(f,{title:'点位图名称',brand:'品牌',product_category:'产品类别',model_pattern:'适用型号',module_name:'模块/板件',version:'版本'});o.status='draft';const d=await api('/api/point-maps',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)});return {silent:true,afterClose:()=>showPointMap(d.map.id)}});
}
async function showPointMap(id,returnAssessmentId=null,backPage=null){
  const d=await api(`/api/point-maps/${id}`),m=d.map,editable=damageKnowledgeEditor()&&m.status==='draft';
  const canAnnotate=damageKnowledgeEditor()&&Boolean(d.image_url);
  if(backPage)pointMapBackPage=backPage;
  activePointMapMarkers=new Map(d.markers.map(x=>[Number(x.id),x]));
  $('#page-title').textContent='点位图';
  const back=returnAssessmentId?`showDamageAssessment(${returnAssessmentId})`:(pointMapBackPage==='point_maps'?'openPointMapLibrary()':'openDamageSopHome()');
  const markers=d.markers.map(x=>`<button type="button" class="point-marker marker-${esc(x.marker_type)}" style="left:${Number(x.x_percent)}%;top:${Number(x.y_percent)}%" aria-label="${esc(x.marker_code)} ${esc(x.label)}" onmouseenter="showPointHover(event,${x.id})" onmousemove="movePointHover(event)" onmouseleave="hidePointHover()" onfocus="showPointHover(event,${x.id})" onblur="hidePointHover()" onclick="event.stopPropagation();showPointMarker(${id},${x.id})"><span>${esc(x.marker_code)}</span></button>`).join('');
  const canvas=d.image_url?`<div class="point-map-scroll can-pan" tabindex="0" aria-label="可拖动的点位图画布"><div class="point-map-canvas ${canAnnotate?'is-editable':''}" data-map-id="${id}"><img src="${d.image_url}" alt="${esc(m.title)}" draggable="false">${markers}</div></div>`:`<div class="point-map-empty"><strong>尚未上传底图</strong><span>上传位号图 PDF 或 PNG/JPG/WebP，系统会把 PDF 页面转换为高清板件底图。</span></div>`;
  const source=d.source_file_url?`<a class="ghost tiny" href="${d.source_file_url}" target="_blank">查看原 PDF${m.source_page?` · 第 ${m.source_page} 页`:''}</a>`:'';
  $('#content').innerHTML=`<div class="toolbar"><button class="ghost" onclick="${back}">← 返回</button><div>${editable?`<button class="ghost" onclick="uploadPointMapImage(${id})">上传/替换位号图</button> `:''}${canAnnotate?`<button class="ghost" onclick="newPointMarker(${id},50,50)">添加点位</button> `:''}${editable?`<button class="primary" onclick="publishPointMap(${id})">发布版本</button>`:''}</div></div><div class="panel"><div class="panel-title"><div><p class="eyebrow">${esc(m.brand)} · ${esc(m.model_pattern)} · ${esc(m.module_name)}</p><h2>${esc(m.title)} · V${esc(m.version)}</h2></div>${badge(m.status)}</div><div class="knowledge-meta"><span>板件代号：${esc(m.board_code||'-')}</span><span>访问：${esc(m.access_level)}</span><span>来源：${esc(m.source_reference||'未登记')}</span>${source}</div>${d.image_url?`<div class="point-map-view-tools"><label>缩放 <input type="range" min="100" max="400" step="25" value="100" oninput="setPointMapZoom(this.value)"></label><output id="point-map-zoom-value">100%</output><span>滚轮可继续滚动页面；缩放后按住底图拖动，方向键也可平移。</span></div>`:''}<div class="point-map-layout"><div>${canvas}${canAnnotate?'<p class="muted point-map-hint">短按图面添加点位；按住拖动只移动画面，不会误加点位。</p>':''}</div><aside class="point-list"><h3>检测点位 <span class="badge">${d.markers.length}</span></h3>${d.markers.length?d.markers.map(x=>`<button onclick="showPointMarker(${id},${x.id})"><span class="point-code">${esc(x.marker_code)}</span><strong>${esc(x.label)}</strong><small>${esc(x.function_description||x.measurement_kind||x.marker_type)}</small><small>${esc(x.voltage_spec||'电压未录入')} · ${esc(x.current_spec||'电流未录入')}</small></button>`).join(''):'<div class="empty">暂无标注点，可先查看位号图，也可由管理员补充。</div>'}</aside></div></div>`;
  if(d.image_url)bindPointMapPan(id,canAnnotate);
}
function setPointMapZoom(value){const canvas=$('.point-map-canvas'),scroll=$('.point-map-scroll');if(canvas&&scroll){const centerX=(scroll.scrollLeft+scroll.clientWidth/2)/Math.max(1,scroll.scrollWidth),centerY=(scroll.scrollTop+scroll.clientHeight/2)/Math.max(1,scroll.scrollHeight);canvas.style.width=`${Number(value)}%`;requestAnimationFrame(()=>{scroll.scrollLeft=centerX*scroll.scrollWidth-scroll.clientWidth/2;scroll.scrollTop=centerY*scroll.scrollHeight-scroll.clientHeight/2})}if($('#point-map-zoom-value'))$('#point-map-zoom-value').textContent=`${value}%`}
async function uploadPointMapImage(id){openModal('上传位号图','<div class="field full"><div class="alert">支持位号图 PDF 和常用图片。PDF 会按所选页转换为高清底图并自动裁掉制版留白；原 PDF 保留为内部附件。</div></div><div class="field full"><label>PDF / PNG / JPG / WebP</label><input name="file" type="file" accept=".pdf,.png,.jpg,.jpeg,.webp" required></div>'+field('page_number','PDF 页码','number','min="1" value="1"')+selectField('auto_crop','自动裁切板件区域',[['true','开启'],['false','关闭']]),async f=>{const d=await api(`/api/point-maps/${id}/image`,{method:'POST',body:f});return {...d,silent:true,afterClose:()=>showPointMap(id,null,pointMapBackPage)}})}
function bindPointMapPan(id,canAnnotate){const scroll=$('.point-map-scroll'),canvas=$('.point-map-canvas');if(!scroll||!canvas)return;let pointerId=null,startX=0,startY=0,startLeft=0,startTop=0,dragged=false;scroll.onpointerdown=event=>{if(event.button!==0||event.target.closest('.point-marker'))return;pointerId=event.pointerId;startX=event.clientX;startY=event.clientY;startLeft=scroll.scrollLeft;startTop=scroll.scrollTop;dragged=false;scroll.setPointerCapture(pointerId)};scroll.onpointermove=event=>{if(event.pointerId!==pointerId)return;const dx=event.clientX-startX,dy=event.clientY-startY;if(!dragged&&Math.hypot(dx,dy)>8){dragged=true;scroll.classList.add('is-panning');hidePointHover()}if(dragged){event.preventDefault();scroll.scrollLeft=startLeft-dx;scroll.scrollTop=startTop-dy}};const finish=event=>{if(event.pointerId!==pointerId)return;const wasDragged=dragged;scroll.classList.remove('is-panning');if(scroll.hasPointerCapture(pointerId))scroll.releasePointerCapture(pointerId);pointerId=null;dragged=false;if(!wasDragged&&canAnnotate){const rect=canvas.getBoundingClientRect(),x=Math.max(0,Math.min(100,(event.clientX-rect.left)*100/rect.width)),y=Math.max(0,Math.min(100,(event.clientY-rect.top)*100/rect.height));newPointMarker(id,x,y)}};scroll.onpointerup=finish;scroll.onpointercancel=event=>{if(event.pointerId===pointerId){scroll.classList.remove('is-panning');pointerId=null;dragged=false}};scroll.onkeydown=event=>{const delta=event.shiftKey?90:36,keys={ArrowLeft:[-delta,0],ArrowRight:[delta,0],ArrowUp:[0,-delta],ArrowDown:[0,delta]};if(!keys[event.key])return;event.preventDefault();scroll.scrollBy({left:keys[event.key][0],top:keys[event.key][1],behavior:'smooth'})}}
function pointMarkerEditorFields(x={}){return field('label','点位名称','text','full required')+field('component_ref','器件/位号')+field('function_description','名称与作用','textarea','full')+field('voltage_spec','适用电压','text','placeholder="例如 3.3 V / 3.1-3.5 V"')+field('current_spec','适用电流','text','placeholder="例如 0.2 A / 最大 1.5 A"')+field('measurement_kind','测量类型','text','placeholder="直流电压、电阻、二极管档、波形等"')+field('expected_value','参考值')+field('tolerance','容差')+field('unit','单位')+field('probe_hint','表笔/探针说明','textarea','full')+field('risk_note','风险提示','textarea','full')}
function fillPointMarkerEditor(form,x){for(const key of ['label','component_ref','function_description','voltage_spec','current_spec','measurement_kind','expected_value','tolerance','unit','probe_hint','risk_note'])if(form.elements[key])form.elements[key].value=x[key]||''}
async function newPointMarker(id,x=50,y=50){openModal('添加检测点位',field('marker_code','点位编号','text','required placeholder="例如 TP12、J3"')+field('x_percent','横坐标 %','number',`step="0.001" min="0" max="100" value="${Number(x).toFixed(3)}" required`)+field('y_percent','纵坐标 %','number',`step="0.001" min="0" max="100" value="${Number(y).toFixed(3)}" required`)+selectField('marker_type','点位类型',[['measurement','测量点'],['connector','连接器'],['component','器件'],['risk','风险点'],['reference','参考点']])+pointMarkerEditorFields(),async f=>{const o=requiredFormValues(f,{marker_code:'点位编号',label:'点位名称',x_percent:'横坐标',y_percent:'纵坐标'});o.x_percent=Number(o.x_percent);o.y_percent=Number(o.y_percent);for(const key of ['component_ref','function_description','voltage_spec','current_spec','measurement_kind','expected_value','tolerance','unit','probe_hint','risk_note'])if(!o[key])delete o[key];const d=await api(`/api/point-maps/${id}/markers`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)});return {...d,silent:true,afterClose:()=>showPointMap(id,null,pointMapBackPage)}})}
async function editPointMarker(mapId,markerId){const x=activePointMapMarkers.get(Number(markerId))||{},body=pointMarkerEditorFields(x);openModal(`编辑 ${x.marker_code||'点位'}`,body,async f=>{const o=Object.fromEntries(f);for(const key of Object.keys(o))if(o[key]==='')o[key]=null;const d=await api(`/api/point-maps/${mapId}/markers/${markerId}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)});return {...d,silent:true,afterClose:()=>showPointMap(mapId,null,pointMapBackPage)}});fillPointMarkerEditor($('#modal-form'),x)}
async function showPointMarker(mapId,markerId){const x=activePointMapMarkers.get(Number(markerId))||(await api(`/api/point-maps/${mapId}`)).markers.find(item=>item.id===Number(markerId));if(!x)return;openModal(`${x.marker_code} · ${x.label}`,`<div class="field full"><div class="marker-detail"><span class="point-code">${esc(x.marker_code)}</span><h3>${esc(x.label)}</h3><p>${esc(x.function_description||'作用说明尚未填写')}</p><dl><div><dt>器件/位号</dt><dd>${esc(x.component_ref||'-')}</dd></div><div><dt>适用电压</dt><dd>${esc(x.voltage_spec||'未录入')}</dd></div><div><dt>适用电流</dt><dd>${esc(x.current_spec||'未录入')}</dd></div><div><dt>测量</dt><dd>${esc(x.measurement_kind||x.marker_type)}</dd></div><div><dt>参考值</dt><dd>${esc(x.expected_value||'-')} ${esc(x.unit||'')} ${x.tolerance?`(${esc(x.tolerance)})`:''}</dd></div><div><dt>探针说明</dt><dd>${esc(x.probe_hint||'-')}</dd></div><div><dt>风险</dt><dd>${esc(x.risk_note||'-')}</dd></div></dl>${damageKnowledgeEditor()?`<button type="button" class="primary" onclick="closeModal();editPointMarker(${mapId},${markerId})">编辑点位说明</button>`:''}</div></div>`,async()=>({silent:true}),{readOnly:true})}
function showPointHover(event,markerId){const x=activePointMapMarkers.get(Number(markerId));if(!x)return;let card=$('#point-hover-card');if(!card){card=document.createElement('div');card.id='point-hover-card';card.className='point-hover-card';document.body.appendChild(card)}card.innerHTML=`<small>${esc(x.marker_code)}${x.component_ref?` · ${esc(x.component_ref)}`:''}</small><strong>${esc(x.label)}</strong><p>${esc(x.function_description||'作用说明尚未填写')}</p><dl><div><dt>电压</dt><dd>${esc(x.voltage_spec||'未录入')}</dd></div><div><dt>电流</dt><dd>${esc(x.current_spec||'未录入')}</dd></div></dl>`;card.classList.add('show');movePointHover(event)}
function movePointHover(event){const card=$('#point-hover-card');if(!card?.classList.contains('show'))return;const rect=event.currentTarget?.getBoundingClientRect?.(),x=event.clientX||((rect?.left||0)+(rect?.width||0)/2),y=event.clientY||rect?.top||0;requestAnimationFrame(()=>{const width=card.offsetWidth,height=card.offsetHeight;card.style.left=`${Math.max(10,Math.min(window.innerWidth-width-10,x+16))}px`;card.style.top=`${Math.max(10,Math.min(window.innerHeight-height-10,y+16))}px`})}
function hidePointHover(){$('#point-hover-card')?.classList.remove('show')}
async function publishPointMap(id){if(!confirm('发布后底图将冻结；管理员仍可继续添加标注点，并修订名称、作用、电压和电流。确认发布？'))return;await api(`/api/point-maps/${id}/publish`,{method:'POST'});toast('点位图已发布');showPointMap(id,null,pointMapBackPage)}
function damageTemplateApplies(template,device){
  const brand=String(template.brand||'').toLowerCase(),pattern=String(template.model_pattern||'').toLowerCase();
  const generic=x=>['*','通用','generic'].includes(x);
  const brandMatches=generic(brand)||brand===String(device?.brand||'').toLowerCase();
  const modelMatches=generic(pattern)||String(device?.model||'').toLowerCase().includes(pattern);
  return brandMatches&&modelMatches;
}
async function newDamageAssessment(preselectedOrderId=null){
  await warm();if(!cache.orders.length){toast('请先创建维修工单',true);return}
  const wrappers=await api('/api/damage-sop/templates?status=published');
  if(!wrappers.length){toast('请先发布至少一个 SOP 模板',true);return}
  openModal('开始工单定损',selectField('repair_order_id','维修工单',cache.orders.map(x=>[x.id,`${x.order_no} · ${customerName(x.customer_id)}`]))+selectField('template_id','SOP 模板',[])+`<div class="field full"><div id="damage-template-note" class="alert">系统会按工单设备筛选适用模板，并固定当前版本步骤。</div></div>`,async f=>{const o=Object.fromEntries(f);o.repair_order_id=Number(o.repair_order_id);o.template_id=Number(o.template_id);const d=await api('/api/damage-assessments',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)});return {silent:true,afterClose:()=>showDamageAssessment(d.assessment.id)}});
  const form=$('#modal-form'),orderSelect=form.elements.repair_order_id,templateSelect=form.elements.template_id,note=$('#damage-template-note');
  const sync=()=>{const order=cache.orders.find(x=>x.id===Number(orderSelect.value)),device=cache.devices.find(x=>x.id===order?.device_id),available=wrappers.filter(x=>damageTemplateApplies(x.template,device));templateSelect.innerHTML=available.map(x=>`<option value="${x.template.id}">${esc(x.template.title)} · V${esc(x.template.version)}</option>`).join('');note.textContent=available.length?`设备：${deviceLabel(device)}；找到 ${available.length} 个适用模板。`:`设备：${deviceLabel(device)}；没有适用的已发布模板。`;form.querySelector('button[type=submit]').disabled=!available.length};
  orderSelect.addEventListener('change',sync);if(preselectedOrderId)orderSelect.value=String(preselectedOrderId);sync();
}
async function showDamageAssessment(id){
  const d=await api(`/api/damage-assessments/${id}`),a=d.assessment,readOnly=a.status!=='in_progress';
  $('#page-title').textContent='定损执行';
  const steps=d.results.map((x,i)=>{const s=x.step_snapshot_json||{},map=s.point_map_id;return `<article class="assessment-step result-${esc(x.result)}"><div class="assessment-step-head"><span class="step-index">${i+1}</span><div><small>${esc(s.section||'未分组')} · ${esc(x.step_code)} · ${esc(damageCheckTypeLabels[s.check_type]||s.check_type)}</small><h3>${esc(s.title||x.step_code)}</h3></div>${damageResultBadge(x.result)}</div><p>${esc(s.instruction||'')}</p>${s.expected_result?`<div class="expected"><strong>合格标准</strong>${esc(s.expected_result)}</div>`:''}${x.measured_value?`<div class="measurement"><strong>实测</strong>${esc(x.measured_value)} ${esc(x.unit||'')}</div>`:''}${x.notes?`<p class="step-notes">${esc(x.notes)}</p>`:''}<div class="step-actions">${map?`<button class="ghost tiny" onclick="showPointMap(${map},${id})">打开点位图</button>`:''}${!readOnly?`<button class="primary tiny" onclick="editDamageAssessmentResult(${id},${x.id})">登记结果</button>`:''}</div></article>`}).join('');
  $('#content').innerHTML=`<div class="toolbar"><button class="ghost" onclick="openDamageSopHome()">← 返回定损中心</button><div>${!readOnly?`<button class="primary" onclick="completeDamageAssessment(${id})">完成定损</button>`:''}</div></div><div class="panel assessment-summary"><div class="panel-title"><div><p class="eyebrow">${recordRef('repair_order',a.repair_order_id,d.order.order_no)} · ${esc(d.device.brand)} ${esc(d.device.model)}</p><h2>${esc(a.assessment_no)} · ${esc(d.template.title)}</h2></div>${badge(a.status)}</div><div class="assessment-progress"><span style="width:${d.progress.percent}%"></span></div><div class="knowledge-meta"><span>进度：${d.progress.completed}/${d.progress.total}（${d.progress.percent}%）</span><span>异常：${d.progress.failed}</span><span>模板版本：V${esc(a.template_version)}</span></div>${readOnly?`<div class="assessment-conclusion"><strong>定损结论</strong><p>${esc(a.conclusion||'-')}</p><span>责任：${esc(a.responsibility||'-')} · 预估：${a.estimated_cost!=null?money(a.estimated_cost):'-'}</span><p>${esc(a.repair_recommendation||'')}</p></div>`:''}</div><div class="assessment-step-list">${steps}</div>`;
}
async function editDamageAssessmentResult(assessmentId,resultId){const d=await api(`/api/damage-assessments/${assessmentId}`),x=d.results.find(item=>item.id===Number(resultId)),s=x.step_snapshot_json||{},attachments=await api(`/api/attachments?repair_order_id=${d.assessment.repair_order_id}`);openModal(`${x.step_code} · ${s.title||'检查步骤'}`,`<div class="field full"><div class="alert">${esc(s.instruction||'')}${s.expected_result?`<br><strong>合格标准：</strong>${esc(s.expected_result)}`:''}</div></div>`+selectField('result','检查结果',[['pass','正常'],['fail','异常'],['na','不适用']])+field('measured_value','实测值')+field('unit','单位')+selectField('evidence_attachment_id','证据附件',[['','不关联'],...attachments.map(a=>[a.id,a.original_filename])])+field('notes','检查记录','textarea','full'),async f=>{const o=Object.fromEntries(f);for(const key of ['evidence_attachment_id']){if(o[key])o[key]=Number(o[key]);else delete o[key]}for(const key of ['measured_value','unit','notes'])if(!o[key])o[key]=null;const updated=await api(`/api/damage-assessments/${assessmentId}/results/${resultId}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)});return {...updated,silent:true,afterClose:()=>showDamageAssessment(assessmentId)}});const form=$('#modal-form');form.elements.result.value=x.result==='pending'?'pass':x.result;form.elements.measured_value.value=x.measured_value||'';form.elements.unit.value=x.unit||'';form.elements.notes.value=x.notes||'';if(x.evidence_attachment_id)form.elements.evidence_attachment_id.value=String(x.evidence_attachment_id)}
async function completeDamageAssessment(id){openModal('完成定损',field('conclusion','定损结论','textarea','full required')+selectField('responsibility','责任判定',[['待进一步确认','待进一步确认'],['客户责任','客户责任'],['产品故障','产品故障'],['外力损坏','外力损坏'],['进液/腐蚀','进液/腐蚀'],['无法判定','无法判定']])+field('estimated_cost','维修预估','number','step="0.01" min="0"')+field('repair_recommendation','维修建议','textarea','full'),async f=>{const o=requiredFormValues(f,{conclusion:'定损结论'});if(o.estimated_cost)o.estimated_cost=Number(o.estimated_cost);else delete o.estimated_cost;const d=await api(`/api/damage-assessments/${id}/complete`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)});return {silent:true,afterClose:()=>showDamageAssessment(d.assessment.id)}})}
const damageRepairWorkbench=workbench;
workbench=async function(id){await damageRepairWorkbench(id);const assessments=await api(`/api/damage-assessments?repair_order_id=${id}`),actions=$('#content .toolbar > div:last-child');if(actions)actions.insertAdjacentHTML('afterbegin',`<button class="ghost" onclick="newDamageAssessment(${id})">开始定损</button> `);const diagnosis=$('#content [data-workbench-section="diagnosis"]');if(diagnosis){const total=diagnosis.querySelector('[data-diagnosis-total]'),diagnosisCount=Number(diagnosis.dataset.diagnosisCount||0);if(total)total.textContent=String(diagnosisCount+assessments.length);diagnosis.insertAdjacentHTML('beforeend',`<div class="diagnosis-subsection diagnosis-sop-subsection"><div class="diagnosis-subheading"><strong>定损 SOP</strong><span>${assessments.length} 项</span></div><div class="diagnosis-sop-list">${assessments.map(x=>`<button class="record-ref" onclick="showDamageAssessment(${x.id})">${esc(x.assessment_no)} · ${esc(labels[x.status]||x.status)}</button>`).join('')||'<div class="muted">尚未创建定损任务</div>'}</div></div>`)}};

const workKindLabels={repair_order:'维修工单',service_ticket:'服务工单',outbound_call:'外呼',followup:'回访',shipment:'物流',email:'邮件',escalation:'专员升级',inventory:'库存'};
function rememberRecent(kind,id){const supported=['repair_order','service_ticket','quote','customer','email'];if(!supported.includes(kind))return;const rows=JSON.parse(localStorage.getItem('service.recentRecords')||'[]').filter(x=>!(x.kind===kind&&Number(x.id)===Number(id)));rows.unshift({kind,id:Number(id),at:Date.now()});localStorage.setItem('service.recentRecords',JSON.stringify(rows.slice(0,10)))}
function recentRecordsHtml(){const rows=JSON.parse(localStorage.getItem('service.recentRecords')||'[]');if(!rows.length)return '<div class="empty">打开工单、客户或报价后会显示在这里</div>';return `<div class="recent-records">${rows.map(x=>`<button onclick="openRecord('${x.kind}',${x.id})"><span>${esc(workKindLabels[x.kind]||x.kind)}</span><strong>#${x.id}</strong><small>${fmtTime(new Date(x.at).toISOString())}</small></button>`).join('')}</div>`}
function favoriteRecords(){return JSON.parse(localStorage.getItem('service.favoriteRecords')||'[]')}
function isFavorite(kind,id){return favoriteRecords().some(x=>x.kind===kind&&Number(x.id)===Number(id))}
function toggleFavorite(kind,id,label=''){const rows=favoriteRecords(),index=rows.findIndex(x=>x.kind===kind&&Number(x.id)===Number(id));if(index>=0){rows.splice(index,1);toast('已取消收藏')}else{rows.unshift({kind,id:Number(id),label:String(label||`#${id}`).slice(0,160),at:Date.now()});toast('已收藏，可在仪表盘快速打开')}localStorage.setItem('service.favoriteRecords',JSON.stringify(rows.slice(0,30)));if(current==='work_center')render.work_center();else if(current==='dashboard')render.dashboard()}
function favoriteRecordsHtml(){const rows=favoriteRecords();if(!rows.length)return '<div class="empty">在待办中点击 ☆ 可收藏常用工单</div>';return `<div class="recent-records">${rows.map(x=>`<button onclick="openRecord('${x.kind}',${x.id})"><span>${esc(workKindLabels[x.kind]||x.kind)}</span><strong>${esc(x.label||`#${x.id}`)}</strong><small>已收藏</small></button>`).join('')}</div>`}
const operationsDashboard=render.dashboard;
render.dashboard=async()=>{await operationsDashboard();$('#content')?.insertAdjacentHTML('beforeend',`<div class="grid-2"><div class="panel"><div class="panel-title"><div><p class="eyebrow">RECENTLY VIEWED</p><h2>最近查看</h2></div><button class="ghost tiny" onclick="localStorage.removeItem('service.recentRecords');loadCurrent()">清空</button></div>${recentRecordsHtml()}</div><div class="panel"><div class="panel-title"><div><p class="eyebrow">PINNED</p><h2>收藏记录</h2></div></div>${favoriteRecordsHtml()}</div></div>`)};

let workCenterView=localStorage.getItem('service.workCenterView')||'all';
function switchWorkView(view){workCenterView=view;localStorage.setItem('service.workCenterView',view);render.work_center()}
function openWorkItem(kind,id){if(['repair_order','service_ticket','email'].includes(kind))return openRecord(kind,id);const page={outbound_call:'calls',followup:'followups',shipment:'shipments',escalation:'escalations',inventory:'inventory'}[kind];if(page){current=page;history.replaceState(null,'',`#${page}`);nav();loadCurrent()}}
render.work_center=async()=>{const [data,team]=await Promise.all([api(`/api/work-center?view=${workCenterView}`),api('/api/team-members')]);cache.team=team;const s=data.summary,tabs=[['all','全部'],['mine','我负责的'],['unassigned','未分派'],['overdue','已超时']];$('#content').innerHTML=`<div class="work-hero"><div><p class="eyebrow">UNIFIED INBOX</p><h2>今天要处理的事</h2><p>维修、服务、回访、物流、邮件和库存预警集中在一处。</p></div><div class="work-summary"><span><strong>${s.total}</strong>当前</span><span><strong>${s.mine}</strong>我负责</span><span><strong>${s.unassigned}</strong>未分派</span><span class="danger-text"><strong>${s.overdue}</strong>已超时</span></div></div><div class="work-controls"><div class="segmented">${tabs.map(([v,l])=>`<button class="${v===workCenterView?'active':''}" onclick="switchWorkView('${v}')">${l}</button>`).join('')}</div><div><button class="ghost" onclick="bulkWork('assign')">批量分派</button> <button class="ghost" onclick="bulkWork('status')">批量改状态</button> <button class="ghost" onclick="bulkWork('due')">批量设时限</button></div></div><div class="work-list">${data.items.map(x=>`<article class="work-row ${x.overdue?'is-overdue':''}"><input class="work-select" type="checkbox" value="${esc(x.key)}" aria-label="选择 ${esc(x.number)}"><button onclick="openWorkItem('${x.kind}',${x.id})"><span class="work-kind">${esc(workKindLabels[x.kind]||x.category)}</span><strong>${esc(x.number)} · ${esc(x.title||'-')}</strong><small>${esc(x.category)} · ${esc(memberName(x.owner_id))}${x.due_at?` · 时限 ${fmtTime(x.due_at)}`:''}</small></button><div>${['repair_order','service_ticket','email'].includes(x.kind)?`<button class="favorite-button" onclick="toggleFavorite('${x.kind}',${x.id},'${esc(x.number)}')" aria-label="${isFavorite(x.kind,x.id)?'取消收藏':'收藏'}">${isFavorite(x.kind,x.id)?'★':'☆'}</button>`:''}${badge(x.status)}${x.overdue?'<span class="badge status-red">已超时</span>':''}</div></article>`).join('')||'<div class="empty">这个视图暂无待办</div>'}</div>`};
function selectedWorkItems(){return [...document.querySelectorAll('.work-select:checked')].map(x=>{const [kind,id]=x.value.split(':');return{kind,id:Number(id)}})}
async function bulkWork(action){const items=selectedWorkItems();if(!items.length)return toast('请先勾选待办',true);let body='',title='';if(action==='assign'){title='批量分派';const choices=['admin','manager'].includes(currentUser?.role)?[['','设为未分派'],...cache.team.map(x=>[x.id,x.display_name])]:[[currentUser.id,`领取给我（${currentUser.display_name}）`]];body=selectField('owner_id','负责人',choices)}else if(action==='due'){title='设置处理时限';body=field('due_at','时限','datetime-local','required')}else{const kinds=new Set(items.map(x=>x.kind));if(kinds.size!==1||![...kinds].every(x=>['repair_order','service_ticket'].includes(x)))return toast('批量改状态时请只选同一种工单',true);title='批量更新状态';const service=[...kinds][0]==='service_ticket';body=selectField('status','新状态',service?[['open','待分派'],['assigned','已分派'],['in_progress','处理中'],['waiting_customer','等待客户'],['waiting_internal','等待内部'],['resolved','已解决'],['closed','已关闭']]:[['pending_inspection','待检测'],['inspecting','检测中'],['pending_quote','待报价'],['repairing','维修中'],['pending_test','待测试'],['pending_shipping','待发货'],['completed','已完成']])+field('reason','变更原因','textarea','full required')}openModal(`${title} · ${items.length} 项`,body,async f=>{const o={items,action,...Object.fromEntries(f)};if(action==='assign')o.owner_id=o.owner_id?Number(o.owner_id):null;if(action==='due'&&!o.due_at)throw new Error('请设置时限');const result=await api('/api/work-center/bulk',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)});if(result.errors.length)toast(`完成 ${result.processed} 项，${result.errors.length} 项失败`,true);return result})}

function supplierFields(){return field('name','供应商名称','text','required')+field('contact','联系人')+field('phone','电话')+field('email','邮箱','email')+field('address','地址','textarea','full')+field('notes','备注','textarea','full')+selectField('enabled','状态',[['true','启用'],['false','停用']])}
async function newSupplier(existing=null){openModal(existing?`编辑供应商 · ${existing.name}`:'新增供应商',supplierFields(),async f=>{const o=Object.fromEntries(f);o.enabled=o.enabled==='true';return api(existing?`/api/suppliers/${existing.id}`:'/api/suppliers',{method:existing?'PATCH':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)})});if(existing){const form=$('#modal-form');for(const key of ['name','contact','phone','email','address','notes'])form.elements[key].value=existing[key]||'';form.elements.enabled.value=String(existing.enabled)}}
function editSupplierById(id){const supplier=(cache.suppliers||[]).find(x=>x.id===Number(id));if(supplier)newSupplier(supplier)}
function addPurchaseLine(item={}){const root=$('#purchase-lines');if(!root)return;const row=document.createElement('div');row.className='purchase-line';row.innerHTML=`<select name="inventory_item_id" required><option value="">选择物料</option>${cache.inventory.filter(x=>x.enabled).map(x=>`<option value="${x.id}" ${Number(item.inventory_item_id)===x.id?'selected':''}>${esc(x.sku)} · ${esc(x.name)}</option>`).join('')}</select><input name="quantity" type="number" min="1" step="1" value="${inventoryQty(item.quantity||1)}" required><input name="unit_cost" type="number" min="0" step="0.01" value="${item.unit_cost||0}" required><input name="remarks" placeholder="备注"><button type="button" class="icon" onclick="this.parentElement.remove()">×</button>`;root.appendChild(row)}
async function newPurchaseOrder(){const [suppliers,inventory]=await Promise.all([api('/api/suppliers'),api('/api/inventory/items')]);cache.suppliers=suppliers;cache.inventory=inventory;if(!suppliers.some(x=>x.enabled))return toast('请先新增并启用供应商',true);if(!inventory.some(x=>x.enabled))return toast('请先新增库存物料',true);openModal('新建采购单',selectField('supplier_id','供应商',suppliers.filter(x=>x.enabled).map(x=>[x.id,x.name]))+field('expected_at','预计到货','datetime-local')+field('notes','采购备注','textarea','full')+`<div class="field full"><div class="panel-title"><label>采购明细</label><button type="button" class="ghost tiny" onclick="addPurchaseLine()">＋ 添加物料</button></div><div class="purchase-line-head"><span>物料</span><span>数量</span><span>含税单价</span><span>备注</span><span></span></div><div id="purchase-lines"></div></div>`,async f=>{const o=Object.fromEntries(f);o.supplier_id=Number(o.supplier_id);if(!o.expected_at)delete o.expected_at;o.items=[...document.querySelectorAll('#purchase-lines .purchase-line')].map(x=>({inventory_item_id:Number(x.querySelector('[name=inventory_item_id]').value),quantity:x.querySelector('[name=quantity]').value,unit_cost:x.querySelector('[name=unit_cost]').value,remarks:x.querySelector('[name=remarks]').value})).filter(x=>x.inventory_item_id);if(!o.items.length)throw new Error('请至少添加一项物料');return api('/api/purchase-orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)})},{variant:'wide'});addPurchaseLine()}
async function showPurchaseOrder(id){const d=await api(`/api/purchase-orders/${id}`),o=d.order,canPay=['admin','manager','finance'].includes(currentUser?.role);openModal(`采购单 · ${o.purchase_no}`,`<div class="field full"><div class="purchase-summary"><span><small>供应商</small><strong>${esc(o.supplier_name)}</strong></span><span><small>采购金额</small><strong>${money(o.total_amount)}</strong></span><span><small>已付 / 待付</small><strong>${money(o.paid_amount)} / ${money(o.payable_amount)}</strong></span><span>${badge(o.status)}</span></div></div><div class="field full">${table(['SKU','物料','订购','已收','已退','单价','金额'],o.items.map(x=>`<tr><td>${esc(x.sku)}</td><td>${esc(x.name)}</td><td>${inventoryQty(x.quantity)}</td><td>${inventoryQty(x.received_quantity)}</td><td>${inventoryQty(x.returned_quantity)}</td><td>${money(x.unit_cost)}</td><td>${money(x.amount)}</td></tr>`))}</div><div class="field full customer-detail-actions">${!['cancelled','closed'].includes(o.status)?`<button type="button" class="primary" onclick="closeModal();receivePurchaseOrder(${id})">到货入库</button> <button type="button" class="ghost" onclick="closeModal();returnPurchaseOrder(${id})">采购退货</button>`:''}${canPay&&Number(o.payable_amount)>0?` <button type="button" class="ghost" onclick="closeModal();payPurchaseOrder(${id})">记录付款</button>`:''}</div>`,async()=>({silent:true}),{readOnly:true,variant:'wide'})}
async function receivePurchaseOrder(id){const d=await api(`/api/purchase-orders/${id}`),items=d.order.items.filter(x=>Number(x.quantity)>Number(x.net_received_quantity));if(!items.length)return toast('该采购单已全部到货');openModal(`到货入库 · ${d.order.purchase_no}`,`<div class="field full receipt-list">${items.map(x=>{const outstanding=Number(x.quantity)-Number(x.net_received_quantity);return `<div data-receipt="${x.id}"><strong>${esc(x.sku)} · ${esc(x.name)}</strong><small>待收 ${inventoryQty(outstanding)}</small><input name="qty-${x.id}" type="number" min="0" max="${inventoryQty(outstanding)}" step="1" value="0" placeholder="本次到货"><input name="lot-${x.id}" placeholder="批次号（留空自动）"><textarea name="serials-${x.id}" placeholder="可选：序列号，逗号或换行分隔"></textarea></div>`}).join('')}</div>`,async f=>{const lines=items.map(x=>({purchase_order_item_id:x.id,quantity:Number(f.get(`qty-${x.id}`)||0),lot_no:String(f.get(`lot-${x.id}`)||'').trim()||null,serial_numbers:String(f.get(`serials-${x.id}`)||'').split(/[\n,，]/).map(v=>v.trim()).filter(Boolean)})).filter(x=>x.quantity>0);if(!lines.length)throw new Error('请填写至少一项到货数量');return api(`/api/purchase-orders/${id}/receive`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({lines})})},{variant:'wide'})}
async function returnPurchaseOrder(id){const d=await api(`/api/purchase-orders/${id}`),items=d.order.items.filter(x=>Number(x.net_received_quantity)>0);if(!items.length)return toast('没有可退的已收物料',true);openModal(`采购退货 · ${d.order.purchase_no}`,selectField('purchase_order_item_id','退货物料',items.map(x=>[x.id,`${x.sku} · ${x.name} · 可退 ${inventoryQty(x.net_received_quantity)}`]))+field('quantity','退货数量','number','min="1" step="1" required')+field('remarks','退货原因','textarea','full required'),async f=>api(`/api/purchase-orders/${id}/return`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({purchase_order_item_id:Number(f.get('purchase_order_item_id')),quantity:f.get('quantity'),remarks:f.get('remarks')})}))}
async function payPurchaseOrder(id){const d=await api(`/api/purchase-orders/${id}`);openModal(`采购付款 · ${d.order.purchase_no}`,`<div class="field full"><div class="alert">待付 ${money(d.order.payable_amount)}</div></div>`+field('amount','付款金额','number',`min="0.01" max="${d.order.payable_amount}" step="0.01" value="${d.order.payable_amount}" required`)+selectField('payment_method','支付方式',[['wechat','微信'],['alipay','支付宝'],['bank','银行'],['cash','现金'],['other','其他']])+field('description','说明','textarea','full'),async f=>api(`/api/purchase-orders/${id}/pay`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(f))}))}
async function newStocktake(){cache.inventory=await api('/api/inventory/items');if(!cache.inventory.length)return toast('暂无库存物料',true);openModal('新建全库盘点',field('notes','盘点说明','textarea','full')+`<div class="field full stocktake-list">${cache.inventory.map(x=>`<label><span><strong>${esc(x.sku)} · ${esc(x.name)}</strong><small>系统 ${inventoryQty(x.stock_quantity)} ${esc(x.unit)}</small></span><input data-stocktake="${x.id}" type="number" min="0" step="1" value="${inventoryQty(x.stock_quantity)}"></label>`).join('')}</div>`,async f=>api('/api/stocktakes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({notes:f.get('notes')||null,items:[...document.querySelectorAll('[data-stocktake]')].map(x=>({inventory_item_id:Number(x.dataset.stocktake),counted_quantity:x.value}))})}),{variant:'wide'})}
async function commitStocktake(id){if(!confirm('提交后将按实盘数量产生库存调整流水，且不可重复提交。继续？'))return;await api(`/api/stocktakes/${id}/commit`,{method:'POST'});toast('盘点已提交');loadCurrent()}
render.procurement=async()=>{const [orders,suppliers,stocktakes,inventory]=await Promise.all([api('/api/purchase-orders'),api('/api/suppliers'),api('/api/stocktakes'),api('/api/inventory/items')]);cache.suppliers=suppliers;cache.inventory=inventory;const payable=orders.reduce((s,x)=>s+Number(x.payable_amount),0),pending=orders.filter(x=>!['received','cancelled','closed'].includes(x.status)).length;$('#content').innerHTML=`<div class="procurement-hero"><div><p class="eyebrow">PURCHASE TO STOCK</p><h2>从采购到库存和付款</h2><p>供应商、分批到货、序列号、退货、付款与盘点集中留痕。</p></div><div class="work-summary"><span><strong>${orders.length}</strong>采购单</span><span><strong>${pending}</strong>待到货</span><span><strong>${money(payable)}</strong>待付</span></div></div><div class="toolbar"><div><button class="ghost" onclick="newSupplier()">新增供应商</button> <button class="ghost" onclick="newStocktake()">发起盘点</button></div><button class="primary" onclick="newPurchaseOrder()">新建采购单</button></div><div class="panel"><div class="panel-title"><h3>采购单</h3></div>${table(['采购单号','供应商','状态','金额','已付','待付','预计到货'],orders.map(x=>`<tr onclick="showPurchaseOrder(${x.id})"><td><button class="record-ref">${esc(x.purchase_no)}</button></td><td>${esc(x.supplier_name)}</td><td>${badge(x.status)}</td><td>${money(x.total_amount)}</td><td>${money(x.paid_amount)}</td><td>${money(x.payable_amount)}</td><td>${fmtTime(x.expected_at)}</td></tr>`))}</div><div class="grid-2"><div class="panel"><h3>供应商</h3>${table(['名称','联系人','电话','状态','操作'],suppliers.map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td>${esc(x.contact||'-')}</td><td>${esc(x.phone||'-')}</td><td>${x.enabled?badge('enabled'):badge('disabled')}</td><td><button class="ghost tiny" onclick="editSupplierById(${x.id})">编辑</button></td></tr>`))}</div><div class="panel"><h3>盘点单</h3>${table(['盘点号','状态','差异项','创建时间','操作'],stocktakes.map(x=>`<tr><td><strong>${esc(x.stocktake_no)}</strong></td><td>${badge(x.status)}</td><td>${x.items.filter(i=>Number(i.difference_quantity)!==0).length}</td><td>${fmtTime(x.created_at)}</td><td>${x.status==='draft'?`<button class="primary tiny" onclick="commitStocktake(${x.id})">提交盘点</button>`:'-'}</td></tr>`))}</div></div>`};

let reportDays=30;
function setReportDays(days){reportDays=days;render.reports()}
render.reports=async()=>{const d=await api(`/api/analytics/operations?days=${reportDays}`),max=Math.max(1,...d.daily.map(x=>Number(x.income)));$('#content').innerHTML=`<div class="toolbar"><div class="segmented">${[[7,'7 天'],[30,'30 天'],[90,'90 天'],[365,'1 年']].map(([n,l])=>`<button class="${n===reportDays?'active':''}" onclick="setReportDays(${n})">${l}</button>`).join('')}</div></div><div class="cards"><div class="card"><small>收款</small><strong>${money(d.totals.income)}</strong></div><div class="card"><small>支出</small><strong>${money(d.totals.expense)}</strong></div><div class="card"><small>退款</small><strong>${money(d.totals.refund)}</strong></div><div class="card"><small>净现金流</small><strong>${money(d.totals.net_cashflow)}</strong></div><div class="card"><small>新建工单</small><strong>${d.totals.orders+d.totals.tickets}</strong></div></div><div class="grid-2"><div class="panel"><h3>每日收款趋势</h3><div class="report-bars">${d.daily.map(x=>`<div title="${x.date} · ${money(x.income)}"><i style="height:${Math.max(3,Number(x.income)/max*100)}%"></i><small>${x.date.slice(5)}</small></div>`).join('')||'<div class="empty">该时段暂无数据</div>'}</div></div><div class="panel"><h3>当前服务负载</h3>${table(['负责人','未结服务工单'],d.workload.map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td>${x.open_tickets}</td></tr>`))}</div></div><div class="panel"><h3>日经营明细</h3>${table(['日期','收款','支出','退款','维修工单','服务工单'],d.daily.slice().reverse().map(x=>`<tr><td>${x.date}</td><td>${money(x.income)}</td><td>${money(x.expense)}</td><td>${money(x.refund)}</td><td>${x.orders}</td><td>${x.tickets}</td></tr>`))}</div>`};

const operationsInventory=render.inventory;
render.inventory=async()=>{await operationsInventory();const toolbar=$('#content .toolbar');toolbar?.insertAdjacentHTML('afterbegin','<input class="search" id="inventory-scan" placeholder="扫码或输入 SKU / 序列号后回车">');if(!['admin','manager','warehouse'].includes(currentUser?.role)){toolbar?.querySelector('button.primary')?.remove();document.querySelectorAll('#content tbody button').forEach(button=>button.remove())}$('#inventory-scan')?.addEventListener('keydown',e=>{if(e.key!=='Enter')return;const q=e.target.value.trim().toLowerCase(),item=cache.inventory.find(x=>String(x.sku).toLowerCase()===q)||cache.inventory.find(x=>[x.sku,x.name,x.compatible_models].some(v=>String(v||'').toLowerCase().includes(q)));if(!item)return toast('未找到匹配物料',true);[...document.querySelectorAll('#content tbody tr')].forEach(row=>row.classList.toggle('scan-match',row.textContent.includes(item.sku)));document.querySelector('.scan-match')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'center'});toast(`已定位 ${item.sku}`)})};

render.backups=async()=>{const [data,schedule]=await Promise.all([api('/api/backups'),api('/api/backups/schedule')]);cache.backupSchedule=schedule;$('#content').innerHTML=`<div class="panel backup-schedule"><div><p class="eyebrow">AUTOMATED BACKUP</p><h3>每日校验备份</h3><p>${schedule.enabled?`已启用，每日 ${esc(schedule.time)} 执行`:'当前未启用'}；保留 ${schedule.retention_days} 天 / 至少 ${schedule.keep_count} 份。${schedule.offsite_dir?`异地副本：${esc(schedule.offsite_dir)}`:''}</p><small>计划任务：${esc(schedule.task_name)}</small></div><button class="primary" onclick="configureBackupSchedule()">配置自动备份</button></div><div class="toolbar"><div class="alert" style="margin:0">备份创建后会自动执行 SQLite 完整性检查和 SHA-256 校验。</div><button class="primary" onclick="createBackup()">立即创建备份</button></div>${table(['文件名','大小','状态','完整性','校验摘要','创建时间','操作'],data.map(x=>`<tr><td><strong>${esc(x.filename)}</strong></td><td>${(Number(x.file_size)/1024/1024).toFixed(2)} MB</td><td>${badge(x.status)}</td><td>${esc(x.integrity_result||'-')}</td><td><code>${esc((x.sha256||'').slice(0,12))}…</code></td><td>${fmtTime(x.created_at)}</td><td><button class="ghost tiny" onclick="verifyBackup(${x.id})">重新校验</button> <a class="ghost tiny link-btn" href="/api/backups/${x.id}/download">下载</a></td></tr>`))}`};
async function configureBackupSchedule(){const s=cache.backupSchedule||await api('/api/backups/schedule');openModal('自动备份计划',selectField('enabled','自动备份',[['true','启用'],['false','停用']])+field('time','每日时间','time','required')+field('retention_days','保留天数','number','min="1" max="3650" required')+field('keep_count','最少保留份数','number','min="1" max="1000" required')+field('offsite_dir','异地副本目录（可选）','text','full placeholder="例如 G:\\Service-Backups 或 NAS 目录"'),async f=>{const o=Object.fromEntries(f);o.enabled=o.enabled==='true';o.retention_days=Number(o.retention_days);o.keep_count=Number(o.keep_count);if(!o.offsite_dir)o.offsite_dir=null;return api('/api/backups/schedule',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)})});const form=$('#modal-form');for(const key of ['enabled','time','retention_days','keep_count','offsite_dir'])form.elements[key].value=key==='enabled'?String(s.enabled):(s[key]??'')}

const clientOrderStatusLabels={pending_payment:'待付款',paid:'已付款',processing:'处理中',shipped:'已发货',completed:'已完成',cancelled:'已取消',refunding:'退款中',refunded:'已退款'};
async function setClientAccountStatus(id,status){if(!confirm(status==='disabled'?'停用该客户账号并撤销全部登录会话？':'重新启用该客户账号？'))return;try{await api(`/api/admin/client/accounts/${id}/status`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status})});toast(status==='disabled'?'客户账号已停用':'客户账号已启用');loadCurrent()}catch(error){toast(error.message,true)}}
async function newClientProductCategory(){openModal('新增商城分类',field('name','分类名称','text','required')+field('slug','英文标识','text','required placeholder="camera-accessories" pattern="[a-z0-9-]+"')+field('sort_order','排序','number','min="0" value="0"')+selectField('enabled','状态',[['true','启用'],['false','停用']]),async f=>{const o=Object.fromEntries(f);o.sort_order=Number(o.sort_order);o.enabled=o.enabled==='true';return api('/api/admin/client/product-categories',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)})})}
async function editClientProductCategory(categoryId){const category=(cache.clientProductCategories||[]).find(x=>x.id===Number(categoryId));if(!category)return toast('分类不存在',true);openModal(`编辑商城分类 · ${category.name}`,field('name','分类名称','text','required')+field('slug','英文标识','text','required pattern="[a-z0-9-]+"')+field('sort_order','排序','number','min="0"')+selectField('enabled','状态',[['true','启用'],['false','停用']]),async f=>{const o=Object.fromEntries(f);o.sort_order=Number(o.sort_order);o.enabled=o.enabled==='true';return api(`/api/admin/client/product-categories/${categoryId}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)})});const form=$('#modal-form');for(const key of ['name','slug','sort_order'])form.elements[key].value=category[key]??'';form.elements.enabled.value=String(category.enabled)}
async function newClientProduct(){
  const [categories,inventory]=await Promise.all([cache.clientProductCategories||api('/api/admin/client/product-categories'),api('/api/inventory/items')]);
  const displayInventory=inventory.filter(x=>x.enabled&&x.client_visible);
  const intro='<div class="field full alert"><strong>一次完成商品发布</strong><br><small>商品信息、首个销售规格、价格和库存会同时保存；主图可选，后续仍可继续增加 SKU 和图片。</small></div>';
  const body=intro
    +selectField('category_id','商品分类',[['','请选择分类'],...categories.map(x=>[x.id,x.name])],'required')
    +field('name','商品名称','text','required maxlength="200"')
    +field('slug','英文标识','text','required maxlength="220" placeholder="例如 mini-4-pro"')
    +field('summary','列表摘要','textarea','full maxlength="500" placeholder="客户在商品列表中首先看到的简短说明"')
    +field('description','商品详情','textarea','full maxlength="20000"')
    +field('after_sales','售后说明','textarea','full maxlength="10000"')
    +'<div class="field full"><h3 style="margin:8px 0 0">首个销售规格</h3><small class="muted">至少创建一个 SKU，客户才能选择规格并加入购物车。</small></div>'
    +selectField('inventory_item_id','关联后台库存物料',[['','不关联（使用独立商城库存）'],...displayInventory.map(x=>[x.id,`${x.sku} · ${x.name}（库存 ${inventoryQty(x.stock_quantity)}）`])])
    +field('sku','SKU 编码','text','required maxlength="80" placeholder="例如 DJI-M4P-STD"')
    +field('sku_name','规格名称','text','required maxlength="200" placeholder="例如 标准版"')
    +field('price','销售价','number','required min="0" step="0.01"')
    +field('original_price','划线价','number','min="0" step="0.01"')
    +field('stock_quantity','可售库存','number','required min="0" max="1000000" step="1" value="0"')
    +field('attributes','规格属性（可选 JSON）','textarea','full placeholder="例如 {&quot;颜色&quot;:&quot;灰色&quot;,&quot;版本&quot;:&quot;标准版&quot;}"')
    +field('image','商品主图（可选）','file','full accept="image/jpeg,image/png,image/webp"')
    +selectField('status','发布方式',[['published','立即上架'],['draft','保存草稿']])
    +selectField('featured','首页推荐',[['false','否'],['true','是']]);
  openModal('发布商城商品',body,async formData=>{
    const raw=Object.fromEntries(formData),image=raw.image;
    let attributes={};
    try{attributes=raw.attributes?JSON.parse(raw.attributes):{}}
    catch{const error=new Error('规格属性必须是有效 JSON');error.fieldName='attributes';throw error}
    const payload={
      product:{category_id:Number(raw.category_id),name:raw.name,slug:raw.slug,summary:raw.summary||null,description:raw.description||null,after_sales:raw.after_sales||null,status:raw.status,featured:raw.featured==='true'},
      sku:{inventory_item_id:raw.inventory_item_id?Number(raw.inventory_item_id):null,sku:raw.sku,name:raw.sku_name,attributes,price:raw.price,original_price:raw.original_price||null,stock_quantity:Number(raw.stock_quantity),enabled:true}
    };
    const created=await api('/api/admin/client/products/publish',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});
    let imageError='';
    if(image?.size){
      const upload=new FormData();
      upload.append('file',image);
      try{await api(`/api/admin/client/products/${created.id}/images`,{method:'POST',body:upload})}
      catch(error){imageError=error.message||'主图上传失败'}
    }
    return{silent:true,afterClose:()=>{
      toast(imageError?`商品已创建，但${imageError}`:(created.status==='published'?'商品已发布':'商品草稿已保存'),Boolean(imageError));
      loadCurrent();
    }};
  },{variant:'wide',submitLabel:'发布商品',busyLabel:'正在发布…'});
  const inventorySelect=$('#modal-form [name=inventory_item_id]');
  inventorySelect?.addEventListener('change',()=>{const item=displayInventory.find(x=>x.id===Number(inventorySelect.value)),form=$('#modal-form');if(!form)return;const stock=form.elements.stock_quantity;if(!item){stock.readOnly=false;return}form.elements.sku.value=item.sku;form.elements.sku_name.value=item.name;form.elements.price.value=item.sale_price;stock.value=inventoryQty(item.stock_quantity);stock.readOnly=true});
}
async function newClientSku(productId){const [inventory]=await Promise.all([api('/api/inventory/items')]),displayInventory=inventory.filter(x=>x.enabled&&x.client_visible),product=(cache.clientProducts||[]).find(x=>x.id===Number(productId));openModal(`新增 SKU · ${product?.name||`商品 #${productId}`}`,selectField('inventory_item_id','关联后台库存物料',[['','不关联'],...displayInventory.map(x=>[x.id,`${x.sku} · ${x.name}`])])+field('sku','SKU 编码','text','required')+field('name','规格名称','text','required')+field('attributes','规格属性（JSON）','textarea','full placeholder="{&quot;颜色&quot;:&quot;灰色&quot;}"')+field('price','销售价','number','min="0" step="0.01" required')+field('original_price','划线价','number','min="0" step="0.01"')+field('stock_quantity','可售库存','number','min="0" step="1" value="0" required')+selectField('enabled','状态',[['true','启用'],['false','停用']]),async f=>{const o=Object.fromEntries(f);try{o.attributes=o.attributes?JSON.parse(o.attributes):{}}catch{throw new Error('规格属性必须是有效 JSON')}o.stock_quantity=Number(o.stock_quantity);o.enabled=o.enabled==='true';o.inventory_item_id=o.inventory_item_id?Number(o.inventory_item_id):null;if(!o.original_price)o.original_price=null;return api(`/api/admin/client/products/${productId}/skus`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)})});const select=$('#modal-form [name=inventory_item_id]');select?.addEventListener('change',()=>{const item=displayInventory.find(x=>x.id===Number(select.value)),form=$('#modal-form');if(!form)return;const stock=form.elements.stock_quantity;if(!item){stock.readOnly=false;return}form.elements.sku.value=item.sku;form.elements.name.value=item.name;form.elements.price.value=item.sale_price;stock.value=inventoryQty(item.stock_quantity);stock.readOnly=true})}
async function uploadClientProductImage(productId,input){const file=input.files?.[0];if(!file)return;const form=new FormData();form.append('file',file);input.disabled=true;try{await api(`/api/admin/client/products/${productId}/images`,{method:'POST',body:form});toast('商品图片已上传');loadCurrent()}catch(error){toast(error.message,true)}finally{input.disabled=false;input.value=''}}
async function editClientProduct(productId){const product=await api(`/api/admin/client/products/${productId}`),categories=cache.clientProductCategories||[];openModal(`编辑商品 · ${product.name}`,selectField('category_id','商品分类',[['','未分类'],...categories.map(x=>[x.id,x.name])])+field('name','商品名称','text','required')+field('slug','英文标识','text','required')+field('summary','列表摘要','textarea','full')+field('description','商品详情','textarea','full')+field('after_sales','售后说明','textarea','full')+selectField('status','上架状态',[['draft','草稿'],['published','上架'],['hidden','隐藏'],['sold_out','售罄']])+selectField('featured','首页推荐',[['false','否'],['true','是']]),async f=>{const o=Object.fromEntries(f);o.category_id=o.category_id?Number(o.category_id):null;o.featured=o.featured==='true';for(const key of ['summary','description','after_sales'])if(!o[key])o[key]=null;return api(`/api/admin/client/products/${productId}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)})},{variant:'wide'});const form=$('#modal-form');for(const key of ['category_id','name','slug','summary','description','after_sales','status'])form.elements[key].value=product[key]??'';form.elements.featured.value=String(product.featured)}
async function showClientProduct(productId){const product=await api(`/api/admin/client/products/${productId}`);cache.clientProductDetails=cache.clientProductDetails||{};cache.clientProductDetails[productId]=product;openModal(`商品内容 · ${product.name}`,`<div class="field full customer-detail-actions"><button type="button" class="primary" onclick="closeModal();editClientProduct(${productId})">编辑商品</button> <button type="button" class="ghost" onclick="closeModal();newClientSku(${productId})">新增 SKU</button></div><div class="field full"><h3>SKU</h3>${table(['编码','规格','库存来源','价格','库存/锁定','状态','操作'],product.skus.map(x=>`<tr><td><code>${esc(x.sku)}</code></td><td>${esc(x.name)}</td><td>${x.inventory?`<strong>${esc(x.inventory.name)}</strong><br><small>${esc(x.inventory.sku)} · ${x.inventory.client_visible?'可展示':'后台专用'}</small>`:'独立商城库存'}</td><td>${money(x.price)}</td><td>${x.inventory?x.inventory.stock_quantity:x.stock_quantity} / ${x.reserved_quantity}</td><td>${x.enabled?badge('enabled'):badge('disabled')}</td><td><button class="ghost tiny" onclick="closeModal();editClientSku(${productId},${x.id})">编辑</button> <button class="danger tiny" onclick="closeModal();deleteClientSku(${x.id})">删除</button></td></tr>`))}</div><div class="field full"><h3>商品图片</h3>${table(['预览','说明','排序','操作'],product.images.map(x=>`<tr><td><img src="${esc(x.url)}" alt="${esc(x.alt_text||'商品图片')}" style="width:64px;height:48px;object-fit:cover;border-radius:8px"></td><td>${esc(x.alt_text||'-')}</td><td>${x.sort_order}</td><td><button class="danger tiny" onclick="closeModal();deleteClientProductImage(${x.id})">移除</button></td></tr>`))}</div>`,async()=>({silent:true}),{readOnly:true,variant:'wide'})}
async function editClientSku(productId,skuId){const product=cache.clientProductDetails?.[productId]||await api(`/api/admin/client/products/${productId}`),sku=product.skus.find(x=>x.id===Number(skuId));if(!sku)return toast('SKU 不存在',true);openModal(`编辑 SKU · ${sku.sku}`,field('sku','SKU 编码','text','required')+field('name','规格名称','text','required')+field('attributes','规格属性（JSON）','textarea','full')+field('price','销售价','number','min="0" step="0.01" required')+field('original_price','划线价','number','min="0" step="0.01"')+field('stock_quantity','可售库存','number',`min="${sku.reserved_quantity}" step="1" required`)+selectField('enabled','状态',[['true','启用'],['false','停用']]),async f=>{const o=Object.fromEntries(f);try{o.attributes=o.attributes?JSON.parse(o.attributes):{}}catch{throw new Error('规格属性必须是有效 JSON')}o.stock_quantity=Number(o.stock_quantity);o.enabled=o.enabled==='true';o.inventory_item_id=sku.inventory_item_id;if(!o.original_price)o.original_price=null;return api(`/api/admin/client/skus/${skuId}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)})});const form=$('#modal-form');for(const key of ['sku','name','price','original_price','stock_quantity'])form.elements[key].value=sku[key]??'';form.elements.attributes.value=JSON.stringify(sku.attributes||{},null,2);form.elements.enabled.value=String(sku.enabled)}
