render.client_platform=async()=>{const [accounts,categories,products,orders,catalog,rules,recycles,forumCategories,posts,reports]=await Promise.all([api('/api/admin/client/accounts'),api('/api/admin/client/product-categories'),api('/api/admin/client/products'),api('/api/admin/client/orders'),api('/api/admin/client/recycle/catalog'),api('/api/admin/client/recycle/rules'),api('/api/admin/client/recycle/requests'),api('/api/admin/client/forum/categories'),api('/api/admin/client/forum/posts'),api('/api/admin/client/forum/reports')]);cache.clientProductCategories=categories;cache.clientProducts=products;cache.clientRecycleRequests=recycles;const pendingOrders=orders.filter(x=>!['completed','cancelled','refunded'].includes(x.status)).length,pendingRecycle=recycles.filter(x=>!['completed','cancelled','rejected'].includes(x.status)).length,pendingReports=reports.filter(x=>x.status==='pending').length;$('#content').innerHTML=`<div class="quick-banner"><div><small>CLIENT BUSINESS</small><h2>客户平台运营中心</h2><p>客户账号与原客户档案绑定；商品、订单、维修、回收和社区共用当前 ERP 数据库。</p></div><a class="primary link-btn" href="/client" target="_blank" rel="noopener">打开客户客户端 →</a></div><div class="cards"><div class="card"><small>客户账号</small><strong>${accounts.length}</strong></div><div class="card"><small>商城商品</small><strong>${products.length}</strong></div><div class="card"><small>待处理商城订单</small><strong>${pendingOrders}</strong></div><div class="card"><small>回收申请</small><strong>${pendingRecycle}</strong></div><div class="card"><small>待处理举报</small><strong>${pendingReports}</strong></div></div><div class="panel"><div class="panel-title"><div><h3>商城商品与内容</h3><p>${categories.length} 个分类 · ${catalog.length} 个回收机型 · ${rules.length} 条估价规则</p></div><div><button class="ghost" onclick="newClientProductCategory()">新增分类</button> <button class="primary" onclick="newClientProduct()">新增商品</button></div></div>${table(['商品','标识','状态','SKU','图片','操作'],products.map(x=>`<tr><td><strong>${esc(x.name)}</strong><br><small>${esc(x.summary||'-')}</small></td><td><code>${esc(x.slug)}</code></td><td>${badge(x.status)}</td><td>${x.sku_count}</td><td>${x.image_count}</td><td><button class="primary tiny" onclick="showClientProduct(${x.id})">管理</button> <label class="ghost tiny link-btn">传图片<input type="file" hidden accept="image/jpeg,image/png,image/webp" onchange="uploadClientProductImage(${x.id},this)"></label> <button class="danger tiny" onclick="deleteClientProduct(${x.id})">删除</button></td></tr>`))}</div><div class="panel"><div class="panel-title"><h3>商城订单</h3><span>支付接口未接入时，仅允许人工凭流水确认收款</span></div>${table(['订单号','客户账号','状态','金额','支付方式','物流','创建时间','操作'],orders.map(x=>`<tr><td><strong>${esc(x.order_no)}</strong></td><td>#${x.account_id}</td><td>${badge(x.status)}</td><td>${money(x.total_amount)}</td><td>${esc(x.payment_provider||'未支付')}</td><td>${esc(x.tracking_no||'-')}</td><td>${fmtTime(x.created_at)}</td><td><button class="primary tiny" onclick="updateClientOrder(${x.id},'${esc(x.status)}')">更新状态</button></td></tr>`))}</div><div class="panel"><div class="panel-title"><div><h3>回收估价与申请</h3><p>参考基价与规则由管理员维护，不向客户展示内部维修物料成本。</p></div><div><button class="ghost" onclick="newRecycleRule()">新增规则</button> <button class="primary" onclick="newRecycleCatalog()">新增机型参考价</button></div></div>${table(['申请号','账号','估价区间','正式报价','状态','时间','操作'],recycles.map(x=>`<tr><td><strong>${esc(x.request_no)}</strong></td><td>#${x.account_id}</td><td>${money(x.reference_min)} – ${money(x.reference_max)}</td><td>${x.staff_quote==null?'-':money(x.staff_quote)}</td><td>${badge(x.status)}</td><td>${fmtTime(x.created_at)}</td><td><button class="primary tiny" onclick="quoteRecycleRequest(${x.id})">正式报价</button></td></tr>`))}</div><div class="grid-2"><div class="panel"><div class="panel-title"><h3>客户账号</h3></div>${table(['账号','手机号','昵称','状态','最近登录','操作'],accounts.map(x=>`<tr><td><strong>${esc(x.username)}</strong><br><small>客户 #${x.customer_id}</small></td><td>${esc(x.phone)}</td><td>${esc(x.nickname)}</td><td>${badge(x.status)}</td><td>${fmtTime(x.last_login_at)}</td><td><button class="${x.status==='active'?'danger':'primary'} tiny" onclick="setClientAccountStatus(${x.id},'${x.status==='active'?'disabled':'active'}')">${x.status==='active'?'停用':'启用'}</button></td></tr>`))}</div><div class="panel"><div class="panel-title"><h3>社区内容</h3><button class="ghost" onclick="newClientForumCategory()">新增板块</button></div><p class="muted">${forumCategories.length} 个板块</p>${table(['帖子','作者','板块','状态','操作'],posts.map(x=>`<tr><td><strong>${esc(x.title)}</strong></td><td>${esc(x.author)}</td><td>${esc(x.category)}</td><td>${badge(x.status)}</td><td><button class="ghost tiny" onclick="moderateClientPost(${x.id},'status','${x.status==='hidden'?'published':'hidden'}')">${x.status==='hidden'?'恢复':'隐藏'}</button> <button class="ghost tiny" onclick="moderateClientPost(${x.id},'pin',${!x.is_pinned})">${x.is_pinned?'取消置顶':'置顶'}</button> <button class="ghost tiny" onclick="moderateClientPost(${x.id},'feature',${!x.is_featured})">${x.is_featured?'取消精选':'精选'}</button></td></tr>`))}<h4>举报队列</h4>${table(['目标','理由','状态','时间','操作'],reports.map(x=>`<tr><td>${x.post_id?`帖子 #${x.post_id}`:`评论 #${x.comment_id}`}</td><td>${esc(x.reason)}</td><td>${badge(x.status)}</td><td>${fmtTime(x.created_at)}</td><td>${x.status==='pending'?`<button class="primary tiny" onclick="moderateClientReport(${x.id},'resolved')">已处理</button> <button class="ghost tiny" onclick="moderateClientReport(${x.id},'dismissed')">驳回</button>`:'-'}</td></tr>`))}</div></div>`};
const clientPlatformOverview=render.client_platform;
render.client_platform=async()=>{await clientPlatformOverview();const [categories,catalog,rules,forumCategories,comments]=await Promise.all([api('/api/admin/client/product-categories'),api('/api/admin/client/recycle/catalog'),api('/api/admin/client/recycle/rules'),api('/api/admin/client/forum/categories'),api('/api/admin/client/forum/comments')]);cache.clientProductCategories=categories;cache.clientRecycleCatalog=catalog;cache.clientRecycleRules=rules;cache.clientForumCategories=forumCategories;$('#content').insertAdjacentHTML('beforeend',`<div class="grid-2"><div class="panel"><div class="panel-title"><h3>商城分类</h3><button class="ghost" onclick="newClientProductCategory()">新增分类</button></div>${table(['名称','标识','排序','状态','操作'],categories.map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td><code>${esc(x.slug)}</code></td><td>${x.sort_order}</td><td>${x.enabled?badge('enabled'):badge('disabled')}</td><td><button class="ghost tiny" onclick="editClientProductCategory(${x.id})">编辑</button></td></tr>`))}</div><div class="panel"><div class="panel-title"><h3>回收机型参考价</h3><button class="ghost" onclick="newRecycleCatalog()">新增机型</button></div>${table(['机型','版本','参考基价','状态','操作'],catalog.map(x=>`<tr><td><strong>${esc(x.brand)} ${esc(x.model)}</strong></td><td>${esc(x.variant||'-')}</td><td>${money(x.reference_price)}</td><td>${x.enabled?badge('enabled'):badge('disabled')}</td><td><button class="ghost tiny" onclick="editRecycleCatalog(${x.id})">编辑</button></td></tr>`))}</div></div><div class="panel"><div class="panel-title"><h3>回收估价规则</h3><button class="ghost" onclick="newRecycleRule()">新增规则</button></div>${table(['编码','规则组','客户说明','乘数','固定调整','状态','操作'],rules.map(x=>`<tr><td><code>${esc(x.code)}</code></td><td>${esc(x.rule_group)}</td><td>${esc(x.label)}</td><td>${x.factor??'-'}</td><td>${money(x.adjustment)}</td><td>${x.enabled?badge('enabled'):badge('disabled')}</td><td><button class="ghost tiny" onclick="editRecycleRule(${x.id})">编辑</button></td></tr>`))}</div><div class="grid-2"><div class="panel"><div class="panel-title"><h3>社区板块</h3><button class="ghost" onclick="newClientForumCategory()">新增板块</button></div>${table(['名称','标识','状态','操作'],forumCategories.map(x=>`<tr><td><strong>${esc(x.name)}</strong><br><small>${esc(x.description||'-')}</small></td><td><code>${esc(x.slug)}</code></td><td>${x.enabled?badge('enabled'):badge('disabled')}</td><td><button class="ghost tiny" onclick="editClientForumCategory(${x.id})">编辑</button></td></tr>`))}</div><div class="panel"><div class="panel-title"><h3>社区评论审核</h3><span>${comments.length} 条可见记录</span></div>${table(['帖子','作者','内容','状态','操作'],comments.map(x=>`<tr><td>#${x.post_id}</td><td>${esc(x.author)}</td><td>${esc(x.content)}</td><td>${badge(x.status)}</td><td><button class="ghost tiny" onclick="moderateClientComment(${x.id},'${x.status==='hidden'?'published':'hidden'}')">${x.status==='hidden'?'恢复':'隐藏'}</button></td></tr>`))}</div></div>`)};

function openClientBusinessPage(page){if(!['client_orders','recycle_pricing','forum_management'].includes(page))return;current=page;history.pushState({page:current},'',`#${current}`);nav();loadCurrent({focus:true})}
async function importRecycleCatalog(input){const file=input.files?.[0];if(!file)return;if(!file.name.toLowerCase().endsWith('.xlsx')){toast('请选择 .xlsx Excel 文件',true);input.value='';return}const form=new FormData();form.append('file',file);input.disabled=true;try{const result=await api('/api/admin/client/recycle/catalog/import',{method:'POST',body:form});toast(`导入完成：新增 ${result.created} 条，更新 ${result.updated} 条`);await loadCurrent()}catch(error){toast(error.message,true)}finally{input.disabled=false;input.value=''}}
render.client_platform=async()=>{const [accounts,categories,products]=await Promise.all([api('/api/admin/client/accounts'),api('/api/admin/client/product-categories'),api('/api/admin/client/products')]);cache.clientProductCategories=categories;cache.clientProducts=products;$('#content').innerHTML=`<div class="quick-banner"><div><small>CLIENT CONFIGURATION</small><h2>客户端设置</h2><p>这里仅维护账号、商城商品与分类；订单、旧机报价和论坛已经拆分为独立一级业务入口。</p></div><a class="primary link-btn" href="/client" target="_blank" rel="noopener">打开客户端 →</a></div><div class="cards"><div class="card"><small>客户账号</small><strong>${accounts.length}</strong></div><div class="card"><small>商城商品</small><strong>${products.length}</strong></div><div class="card"><small>商品分类</small><strong>${categories.length}</strong></div></div><div class="home-actions"><button type="button" onclick="openClientBusinessPage('client_orders')"><span class="home-action-icon">商</span><span><strong>客户端订单</strong><small>独立处理商城订单流转</small></span><em>›</em></button><button type="button" onclick="openClientBusinessPage('recycle_pricing')"><span class="home-action-icon">旧</span><span><strong>旧机报价</strong><small>参考价、规则与申请</small></span><em>›</em></button><button type="button" onclick="openClientBusinessPage('forum_management')"><span class="home-action-icon">坛</span><span><strong>论坛管理</strong><small>板块、帖子与举报审核</small></span><em>›</em></button></div><div class="panel"><div class="panel-title"><div><h3>商城商品</h3><p>商品发布、库存关联与内容维护。</p></div><div><button class="ghost" onclick="newClientProductCategory()">新增分类</button> <button class="primary" onclick="newClientProduct()">新增商品</button></div></div>${table(['商品','标识','状态','SKU','图片','操作'],products.map(x=>`<tr><td><strong>${esc(x.name)}</strong><br><small>${esc(x.summary||'-')}</small></td><td><code>${esc(x.slug)}</code></td><td>${badge(x.status)}</td><td>${x.sku_count}</td><td>${x.image_count}</td><td><button class="primary tiny" onclick="showClientProduct(${x.id})">管理</button> <label class="ghost tiny link-btn">传图片<input type="file" hidden accept="image/jpeg,image/png,image/webp" onchange="uploadClientProductImage(${x.id},this)"></label> <button class="danger tiny" onclick="deleteClientProduct(${x.id})">删除</button></td></tr>`))}</div><div class="grid-2"><div class="panel"><div class="panel-title"><h3>商城分类</h3><button class="ghost" onclick="newClientProductCategory()">新增分类</button></div>${table(['名称','标识','排序','状态','操作'],categories.map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td><code>${esc(x.slug)}</code></td><td>${x.sort_order}</td><td>${x.enabled?badge('enabled'):badge('disabled')}</td><td><button class="ghost tiny" onclick="editClientProductCategory(${x.id})">编辑</button></td></tr>`))}</div><div class="panel"><div class="panel-title"><h3>客户账号与识别码</h3></div>${table(['唯一识别码','手机号','昵称','状态','最近登录','操作'],accounts.map(x=>`<tr><td><strong>${esc(x.identifier||`@${x.username}`)}</strong><br><small>客户 #${x.customer_id}</small></td><td>${esc(x.phone)}</td><td>${esc(x.nickname)}</td><td>${badge(x.status)}</td><td>${fmtTime(x.last_login_at)}</td><td><button class="${x.status==='active'?'danger':'primary'} tiny" onclick="setClientAccountStatus(${x.id},'${x.status==='active'?'disabled':'active'}')">${x.status==='active'?'停用':'启用'}</button></td></tr>`))}</div></div>`};
