function enhanceSearchableSelects(root=document){
  const selects=[];
  if(root instanceof HTMLSelectElement)selects.push(root);
  if(root.querySelectorAll)selects.push(...root.querySelectorAll('select'));
  for(const select of selects){
    const optionCount=[...select.options].filter(option=>option.value||!option.disabled).length;
    const existing=select.previousElementSibling?.classList.contains('select-quick-search')?select.previousElementSibling:null;
    if(optionCount<=10){if(existing)existing.remove();delete select.dataset.searchableEnhanced;continue}
    if(existing){existing.dispatchEvent(new Event('input'));continue}
    const search=document.createElement('input');search.type='search';search.className='select-quick-search';search.placeholder='输入关键词检索选项';search.setAttribute('aria-label','检索下拉选项');search.autocomplete='off';
    search.addEventListener('input',()=>{const keyword=search.value.trim().toLocaleLowerCase('zh-CN'),selected=select.value;for(const option of select.options)option.hidden=Boolean(keyword)&&option.value!==selected&&!option.textContent.toLocaleLowerCase('zh-CN').includes(keyword)});
    select.before(search);select.dataset.searchableEnhanced='true'
  }
}
let selectEnhanceFrame=0;
const searchableSelectObserver=new MutationObserver(records=>{cancelAnimationFrame(selectEnhanceFrame);selectEnhanceFrame=requestAnimationFrame(()=>{for(const record of records)enhanceSearchableSelects(record.target)})});
if(document.body){searchableSelectObserver.observe(document.body,{childList:true,subtree:true});enhanceSearchableSelects(document)}

