render.settings=async()=>{await operationsSettings();const d=await api('/api/integrations/status');const cards=[['SMTP 邮件',d.smtp.configured,d.smtp.configured?`${d.smtp.sender} · ${d.smtp.host}`:'等待配置'],['企业微信',d.wecom.configured,d.wecom.message],['顺丰接口',d.sf_express.configured,d.sf_express.message]];$('#content')?.insertAdjacentHTML('afterbegin',`<div class="integration-grid">${cards.map(x=>`<article><span class="integration-dot ${x[1]?'ready':'pending'}"></span><div><small>外部服务诊断</small><strong>${esc(x[0])}</strong><p>${esc(x[2])}</p></div>${badge(x[1]?'configured':'pending')}</article>`).join('')}</div>`)};
document.addEventListener('keydown',e=>{const command=e.ctrlKey||e.metaKey,key=String(e.key||'').toLowerCase(),dialog=topDialog();if(e.key==='Tab'&&dialog){trapDialogFocus(e,dialog);return}if(command&&key==='f'){e.preventDefault();openGlobalSearch();return}if(command&&!isEditableTarget(e.target)&&(key==='z'||key==='y')){e.preventDefault();if(key==='y'||(key==='z'&&e.shiftKey))redoAppAction();else undoAppAction();return}if(e.key==='Escape'&&!$('#global-search').classList.contains('hidden')){closeGlobalSearch();return}if(e.key==='Escape'&&!$('#modal').classList.contains('hidden')){closeModal();return}if(e.key==='Escape'&&!$('#mobile-nav-layer')?.classList.contains('hidden')){closeMobileNav();return}if(e.key==='Escape')closeAccountMenu()});
document.addEventListener('click',e=>{if(!e.target.closest('.account-menu'))closeAccountMenu();document.querySelectorAll('.action-menu[open]').forEach(menu=>{if(!menu.contains(e.target)||e.target.closest('.action-menu-panel button'))menu.removeAttribute('open')})});
$('#modal').addEventListener('click',e=>{if(e.target.id==='modal'&&!matchMedia('(prefers-reduced-motion: reduce)').matches)$('#modal .modal-card')?.animate?.([{transform:'scale(1)'},{transform:'scale(.992)'},{transform:'scale(1)'}],{duration:180,easing:'cubic-bezier(0.23, 1, 0.32, 1)'})});
async function monitorHostConnection(){const wasLost=connectionLost;try{const response=await fetch('/api/health',{cache:'no-store'});if(!response.ok)throw new Error();setConnectionState(true);if(wasLost&&currentUser)await loadCurrent()}catch{setConnectionState(false)}}
window.addEventListener('online',monitorHostConnection);
window.addEventListener('offline',()=>setConnectionState(false));
setInterval(monitorHostConnection,15000);
window.addEventListener('popstate',()=>{const next=location.hash.slice(1)||'dashboard';if(next===current||!pages.some(x=>x[0]===next))return;current=next;closeMobileNav({restoreFocus:false});closeAccountMenu();nav();loadCurrent({focus:true})});
window.addEventListener('DOMContentLoaded',async()=>{bindGlobalSearch();current=location.hash.slice(1)||'dashboard';history.replaceState({page:current},'',`#${current}`);try{const status=await api('/api/auth/status');applyBranding(status.brand_name);if(!status.initialized){showAuth('setup');return}const data=await api('/api/auth/me');await completeAuth(data)}catch(e){showAuth('login',e.message)}});
